// Crimson-Desert-Wiki — Datenbestand, am 23.08.2026 aus index.html ausgelagert.
// REIHENFOLGE IST TRAGEND: Bloecke referenzieren frueher definierte (TDZ) — nicht umsortieren,
// Datei laedt als klassisches Script-Tag (src) VOR dem Hauptscript in index.html.
// Enthaelt: ITEMS, ITEM_BEREICHE, SANCTUM_GUIDE, CHAPTERS, SIDE_QUESTS
const ITEMS=[
  {name:"Hunter's Sigil",cat:"Pet-Ausrüstung — Vogel",detail:"Neu mit Patch 1.13.00. Ausrüstungs-Sigil für Vogel-Pets: Ausgerüstet lässt es den Vogel selbstständig Beute (prey) und Sammelobjekte passend zu seiner Spezialisierung apportieren — eine reine Sammel-/Loot-Funktion, kein Kampf. Gegenstück zum 'Sigil of Valor' (Kampf); pro Vogel entscheidet man sich faktisch für eine der beiden Rollen. Interner Item-Code deutet auf ein Pet-Amulett hin.",loc:"Verkauf durch die wandernde Pet-Händlerin Lacey (kein fester Stand) für 800 Kupfer (= 8 Silber; questlog 1004315) — tagsüber auf den Hauptwegen um Pororin/Florindale (Hernand) anzutreffen, z.B. morgens beim großen Baum in Florindale. Voraussetzung: Abschluss der Trembling-Woods-Questreihe (bereits erfüllt, wer via Sotdae of Bond Vögel gezähmt hat). Quelle: keengamer, thegameswiki, VULKK.",miss:false,conf:"high",icon:"/assets/_sprites/itemicon_cd_pet_huntable_amulet.webp"},
  {name:"Sigil of Valor",cat:"Pet-Ausrüstung — Vogel",detail:"Pet-Ausrüstungs-Sigil, das ein Pet aktiv am Kampf teilnehmen lässt: Es greift nahe Gegner automatisch an (wirkt vor allem gegen starke Gegner mit viel HP), statt nur nach dem Kampf zu looten. Anlegbar auf Hunde und Baby-Wyverns; seit Patch 1.13.00 auch auf Iron Eagle und Phoenix (die Freischaltung war in 1.11.00 zunächst wieder gestrichen worden). Nicht mit dem neuen 'Hunter's Sigil' (reine Sammel-Funktion) verwechseln.",loc:"Bei der wandernden Geheimhändlerin Lacey (Shai-NPC) im Raum Pororin/Florindale (meist im Nebendorf Florindale), 800 Kupfer (= 8 Silber; per questlog bestätigt). Vorbedingung laut Guides: Abschluss der 'Unreachable Village'-Fraktions-Questreihe — unbestätigt, beim 'Hunter's Sigil' nennen die Quellen stattdessen die Trembling-Woods-Reihe. Quelle: questlog.gg (Item 1004287), Gfinity Esports, game8, PC Gamer. Hinweis (Prüfung 11.08.2026): Die drei Guide-Quellen waren zeitweise nicht abrufbar.",miss:false,conf:"medium",icon:"/assets/_sprites/itemicon_cd_pet_brave_amulet.webp"},
  {name:"Firefly Lantern",cat:"Werkzeug — Lampe",detail:"Legendäre Laterne, die seit Generationen im Longleaf Forest weitergegeben wird. Wenn ihr Licht scheint, steigen kleine glühwürmchenartige Geister auf und lindern Wunden mit warmer Energie. Zusatzfähigkeit 'Firefly Dust' (Laterne per Quick Slot einschalten, laut questlog); Werte (Heilmenge, Dauer) nicht erfasst.",loc:"Belohnung der Quest 'Bright Longleaf Forest' (Longleaf Tribe, Pailune): Mission 'Dissipated Fog' bzw. 'Deliver the news of Moren's defeat' (Nachricht vom Sieg über Moren the Mistwood Huntmaster überbringen). questlog führt beide Missionen mit denselben Belohnungen (u. a. Shadowleaf Bow, Slave Gladiator Branding Spear, Rosehorn Deer). Freischaltung des Longleaf Tribe über die Skoghorn-Kette 'Soul Shepherd' (White Horn); die Pailune-Miliz-Voraussetzung nennen Sportskeeda, Fextralife und gamerguides. Keine Quelle führt die Laterne als verpassbar. Quelle: questlog (Item 1000858, Mission 1000549), camzillasmom, Sportskeeda, Fextralife, gamerguides.com",miss:false,conf:"high",icon:"/assets/_sprites/itemicon_prefab_cd_t0000_lantern_0009_on.webp"},
  {name:"Lantern",cat:"Werkzeug — Lampe",detail:"Basis-Laterne und tragbare Lichtquelle zum Ausleuchten dunkler Bereiche (Kerze oder Öl in einem Eisenrahmen). Sie heftet sich an Kliffs Ausrüstung und bleibt entzündet, ohne die Hände für Kampf oder Erkundung zu blockieren; sie kann manuell hochgehalten (gerichtetes Licht) oder im Auto-Modus genutzt werden. In der Nähe von Memory Fragments pulsiert sie und leuchtet blau, als Signal, dort mit dem Visione zu lesen, und hilft, Spuren und Hinweise für bestimmte Rätsel sichtbar zu machen. Aktivierung: L1/LB/Strg halten; Ein/Aus über das Ausrüstungs-Radialmenü (Links-D-Pad bzw. F2). Am Blacksmith verbesserbar.",loc:"Standardmäßig im Verlauf der Quest 'Unknown Space' (Prolog 'Dead of Night') freigeschaltet. Ersatz beim Provisioner's Shop für 10 Kupfer überall in Pywel kaufbar. Quelle: Game8, Fextralife",miss:false,conf:"high",icon:"/assets/_sprites/itemicon_lantern_on.webp"},
  {name:"Torch",cat:"Werkzeug — Lampe",detail:"Eine Fackel aus öldurchtränktem Tuch um ein Stockende. Große, helle Flamme, die einen weiten Bereich ausleuchtet. Kann notfalls als Waffe dienen (geringer Schaden); wegen der Brandgefahr ist Vorsicht geboten. Nicht am Blacksmith verbesserbar.",loc:"Basispreis 85; die Bezugsquelle ist auf der Fextralife-Seite nicht angegeben, und in den questlog-Spieldaten gibt es kein Item 'Torch' (nur die eigenständigen Gegenstände 'Tripod Guide Torch' und 'Tripod Guardian Torch'). Quelle: Fextralife",miss:false,conf:"medium",icon:"cd_assets/items/torch.webp"},
  {name:"Blue Scout Lantern",cat:"Werkzeug — Lampe",detail:"Eine Laterne für Kundschafter, die Neuigkeiten aus ganz Pywel schneller als alle anderen sammeln. Ihr Licht soll den Weg ins Abenteuer weisen und helfen, Pywels zahllose Geheimnisse aufzudecken. Keine Statboni; nicht am Blacksmith verbesserbar.",loc:"Bezugsquelle auf der Wiki-Seite nicht angegeben. Als einzigartige Laterne geführt. Quelle: Fextralife, Sportskeeda",miss:false,conf:"medium",icon:"/assets/_sprites/itemicon_prefab_cd_t0000_lantern_0008_index02_on.webp"},
  {name:"Dark Fog Lantern",cat:"Werkzeug — Lampe",detail:"Eine dekorative, regen- und windfeste Laterne. Ihr Licht durchdringt selbst die dichtesten Tiefen jeder Nebelwolke, daher ihr Name. Nützlich in stark vernebelten Gebieten. Basispreis 240.",loc:"Bezugsquelle auf der Wiki-Seite nicht angegeben. Als einzigartige Laterne geführt. Quelle: Fextralife, Sportskeeda",miss:false,conf:"medium",icon:"/assets/_sprites/itemicon_prefab_cd_t0000_lantern_0003_on.webp"},
  {name:"Fancy Flame-Patterned Lantern",cat:"Werkzeug — Lampe",detail:"Eine mit Flammenmustern durchbrochene Laterne. Beim Entzünden flackern die Schatten und erzeugen eine eindrucksvolle Atmosphäre. Eher Dekoration als praktischer Nutzen.",loc:"Bezugsquelle nicht angegeben; Basispreis 240 (vermutlich Händler). Als einzigartige Laterne geführt. Quelle: Fextralife, Sportskeeda",miss:false,conf:"medium",icon:"/assets/_sprites/itemicon_prefab_cd_t0000_lantern_0005_on.webp"},
  {name:"Flame Lantern",cat:"Werkzeug — Lampe",detail:"Eine robuste Laterne aus Eisen mit dünnem Eisenbeschlag in Form einer brennenden Flamme. Wegen ihres Gewichts und dekorativen Aussehens beliebt. Eine Refinement-Tabelle ist vorhanden, aber nur bis +0 dokumentiert (kein nennenswertes Upgrade).",loc:"Bezugsquelle nicht näher angegeben; Basispreis 240 (vermutlich Händler). Quelle: Fextralife",miss:false,conf:"medium",icon:"/assets/_sprites/itemicon_prefab_cd_t0000_lantern_0004_on.webp"},
  {name:"Purple Scout Lantern",cat:"Werkzeug — Lampe",detail:"Eine Laterne für Kundschafter, die Neuigkeiten aus ganz Pywel schneller als alle anderen sammeln. Ihr Licht weist den Weg ins Abenteuer und hilft, Pywels Geheimnisse aufzudecken (gleiche Beschreibung wie Blue Scout Lantern, andere Färbung). Keine Statboni; nicht am Blacksmith verbesserbar.",loc:"Bezugsquelle nicht angegeben; Existenz und Beschreibung über mehrere Datenbanken bestätigt (questlog item 1003190, crimsondb.gg). Quelle: questlog.gg, crimsondb.gg, Fextralife",miss:false,conf:"medium",icon:"/assets/_sprites/itemicon_prefab_cd_t0000_lantern_0008_index01_on.webp"},
  {name:"Shiny Blue Sea Lantern",cat:"Werkzeug — Lampe",detail:"Eine dekorative Laterne, beliebt bei den Shais; nachdem ein Shai sie ins Dorf brachte, verbreitete sie sich schnell. Ein goldener Rand mit blauem Glas macht sie im entzündeten Zustand besonders schön. Überwiegend dekorativ.",loc:"Bezugsquelle nicht angegeben; Basispreis 240 (vermutlich Händler). Als einzigartige Laterne geführt. Quelle: Fextralife, Sportskeeda",miss:false,conf:"medium",icon:"/assets/_sprites/itemicon_prefab_cd_t0000_lantern_0002_on.webp"},
  {name:"Shroud Lantern",cat:"Werkzeug — Lampe",detail:"Eine fein gefertigte, hochwertige Laterne, dem Crimson-Desert-Stil ähnlich, aber subtil anders. Gebrauchsspuren am Griff deuten darauf hin, dass sie zuvor in der rechten Hand getragen wurde (vermutlich mit einer Waffe in der linken). Nicht am Blacksmith verbesserbar.",loc:"Bezugsquelle/Quest auf der Wiki-Seite nicht angegeben; nur über Fextralife belegt. Quelle: Fextralife",miss:false,conf:"medium",icon:"/assets/_sprites/itemicon_prefab_cd_t0000_lantern_0006_on.webp"},
  {name:"Wooden Lantern",cat:"Werkzeug — Lampe",detail:"Eine einfache, leichte Laterne aus Holz, gefertigt aus leicht verfügbaren Materialien. Wird wegen der Brandgefahr seltener genutzt als Metalllaternen. In der Refinement-Tabelle nur +0 (kein nennenswertes Upgrade).",loc:"Bezugsquelle auf der Wiki-Seite nicht angegeben (vermutlich käuflich/einfach verfügbar). Auch in der Liste der einzigartigen Laternen geführt. Quelle: Fextralife, Sportskeeda",miss:false,conf:"medium",icon:"/assets/_sprites/itemicon_prefab_cd_t0000_lantern_0007_on.webp"},
  {name:"Bernor's Pickaxe",cat:"Werkzeug — Bergbau",detail:"Effekt: Mining Yield Up Lv 2 (höhere Ertragsstufe als Fine Pickaxe) mit \"Chance to Mine Additional Materials\" 20% -> 30%. Wird aus einem Blueprint gefertigt (u. a. 30 Fine Timber, 20 Iron Ore, 10 Sturdy Hide, 10 Diamonds bei einem Schmied). Beste reguläre Spitzhacke für maximalen Erzertrag.",loc:"Blueprint kaufbar bei Bernor im Mineral Shop von Fort Manub in Tashkalp (Crimson Desert / Wüstenregion); zuvor Fort Manub befreien und Bernors Vertrauen (Geschenke) aufbauen. Quelle: VULKK; Quelle: Nerdschalk; Quelle: GameRant",miss:false,conf:"high",icon:"/assets/_sprites/itemicon_prefab_cd_t0000_pickaxe_0003.webp"},
  {name:"Fine Pickaxe",cat:"Werkzeug — Bergbau",detail:"Effekt: Mining Yield Up Lv 1 mit \"Chance to Mine Additional Materials\" 20% -> 30% (steigt durch Refinement). Höhere Grundchance auf Zusatzmaterialien als die Standard-Spitzhacke, bei gleicher Ertragsstufe. Wird aus einem Blueprint gefertigt.",loc:"Blueprint kaufbar im Mineral Shop in Karin Quarry, Hernand. Quelle: VULKK; Quelle: Game8",miss:false,conf:"high",icon:"/assets/_sprites/itemicon_prefab_cd_t0000_pickaxe_0001_index01.webp"},
  {name:"Mining Knuckledrill",cat:"Werkzeug — Bergbau",detail:"Elektrisches Bergbau-Werkzeug (nur von Kliff nutzbar). Effekt: Mining Yield Up Lv 1 -> 2 durch Verbesserung, \"Chance to Mine Additional Materials\" 10% -> 30%; voll aufgewertet erreicht es die Erträge von Bernor's Pickaxe und sammelt abgebautes Erz zusätzlich automatisch ein. Dieses Werkzeug ist zugleich eine Knuckles-Waffe und erscheint auch im Waffen-Tab.",loc:"Belohnung für den Sieg über den Boss Marni's Excavatron (Faktions-Quest \"Stolen Quarry\"); zusätzlich als Drop von Bleed Bandits in Karin Quarry sowie per Missions-Dispatch (Vorwork Armory in Demeniss oder Karin Quarry in Hernand) nach Abschluss der Forschung \"Electric Tool Design Research\" am Dewhaven Keep Institute in Delesyia. Quelle: VULKK; Quelle: Game8; Quelle: Nerdschalk",miss:false,conf:"high",icon:"/assets/_sprites/itemicon_prefab_cd_phm_13_fist_0014_r.webp"},
  {name:"Pickaxe",cat:"Werkzeug — Bergbau",detail:"Standard-Spitzhacke (Attack 8, Fähigkeit \"Mining Mastery\"). Effekt: Mining Yield Up Lv 1 mit 10% Chance auf zusätzliches Erz pro Schlag. Bei voller Verbesserung (+10 Refinement) steigt der Angriffswert auf 31, die 10%-Bonuschance bleibt aktiv. Erhöht den Erz-/Mineral-Ertrag deutlich gegenüber Notmethoden wie Force Palm oder Explosivpfeilen.",loc:"Standard-Werkzeug, früh erhältlich bei Händlern/Schmieden in Hernand (z.B. Equipment Shop). Quelle: Fextralife; Quelle: Nerdschalk; Quelle: VULKK",miss:false,conf:"high",icon:"/assets/_sprites/itemicon_prefab_cd_t0000_pickaxe_0001.webp"},
  {name:"Demenissian Chainsaw",cat:"Werkzeug — Holzfällen",detail:"Elektrische Kettensäge (laut Patch 1.11.00 vom 12.06.2026 auch von Damiane und Oongka ausrüstbar, zuvor nur Kliff); fällt Bäume schneller. Effekt: Logging Quality Up Lv 1 -> 2 durch Verbesserung, \"Chance to Log Additional Timber\" 10% -> 30% - voll aufgewertet erreicht sie die Erträge von Olvald's Logging Axe und sammelt gefälltes Timber zusätzlich automatisch ein.",loc:"Per Missions-Dispatch (Vorwork Armory in Demeniss oder Steelspike Armory in Delesyia) nach Abschluss der Forschung \"Electricity - Movement Conversion Mechanism Research\". Seit Patch 2.00.00 (25.08.2026) kann die Kettensäge im Camp gespendet werden (offizielle Notes, keine Gegenleistung genannt). questlog führt sie als Belohnung der Entsendung „Chainsaw Production“. Quelle: VULKK; Quelle: Game8; Patch-Notes 2.00.00",miss:false,conf:"high",icon:"/assets/_sprites/itemicon_prefab_cd_phm_13_fist_0016_r.webp"},
  {name:"Fine Logging Axe",cat:"Werkzeug — Holzfällen",detail:"Effekt: Logging Quality Up Lv 1 mit \"Chance to Log Additional Timber\" 20% -> 30%. Höhere Chance auf Fine Timber und (durch Refinement) auf zusätzliches Timber als die Standard-Axt. Wird aus einem Blueprint gefertigt.",loc:"Blueprint kaufbar im Provisioner's Shop in Odeck, nordwestliches Pailune. Quelle: VULKK; Quelle: Game8",miss:false,conf:"high",icon:"/assets/_sprites/itemicon_prefab_cd_t0000_axe_0001_index01.webp"},
  {name:"Logging Axe",cat:"Werkzeug — Holzfällen",detail:"Standard-Fällaxt (Attack 8, Fähigkeit \"Logging Mastery\"). Effekt: Logging Quality Up Lv 1 zum Fällen und Zerteilen von Bäumen für Timber; bei voller Verbesserung (+10) zusätzlich 10% Chance auf zusätzliches Timber. Verschiedene Timber-Qualitäten werden zum Aufwerten der meisten Bogen und einiger Schilde benötigt.",loc:"Standard-Werkzeug: gratis durch Annahme von Turnali's Request (Schmied in Hernand) oder Kauf im Provisioner's Shop für 29 Copper (Flaschen-Symbol-Shops, u.a. in Pywell). Quelle: Game8; Quelle: Fextralife",miss:false,conf:"high",icon:"/assets/_sprites/itemicon_prefab_cd_t0000_axe_0001.webp"},
  {name:"Olvald's Logging Axe",cat:"Werkzeug — Holzfällen",detail:"Effekt: Logging Quality Up Lv 2 (höhere Qualitätsstufe als Fine Logging Axe) mit \"Chance to Log Additional Timber\" 20% -> 30%. Beste reguläre Fällaxt, direkt von allen Charakteren nutzbar (langsamer als die Demenissian Chainsaw). Wird aus einem gefundenen Blueprint gefertigt.",loc:"Blueprint liegt auf einem Tisch im Longbranch Shade Hideout nördlich von Skallcove, Pailune. Quelle: VULKK; Quelle: Game8",miss:false,conf:"high",icon:"/assets/_sprites/itemicon_prefab_cd_t0000_axe_0002.webp"},
  {name:"Broom",cat:"Werkzeug — Sammeln",detail:"Besen. In-Game-Beschreibung (Game8/crimsondb, verbatim): \"Cleaning Tool for Sweeping Floors\". Laut VULKK in zwei Quests benötigt (vom Spiel gestellt) und in der 'Pine Broom Challenge' (gegen Bären) eingesetzt; es existiert eine 'Sturdy Broom'-Variante (questlog 1003848, bei Händlern für 85 Kupfer; Abyss-Sockel laut VULKK, im Item-Text nicht erwähnt).",loc:"Vom Spiel im Questkontext bereitgestellt; zusätzlich bei Händlern für 58 Kupfer kaufbar (questlog: u. a. Ronnard, Kiki, Wynstan). Quelle: questlog.gg, Game8, Fextralife, VULKK",miss:false,conf:"high",icon:"/assets/_sprites/itemicon_prefab_cd_t0000_broom_0001.webp"},
  {name:"Extra Large Bag",cat:"Werkzeug — Sammeln",detail:"Großer Beutel, der die Inventarkapazität dauerhaft um 10 Slots erweitert. Er liegt neben einem zerbrochenen Karren in den Hills of No Return (nordöstlich von Hernand, südwestlich der Arboria-Werkstatt) und respawnt alle sieben Ingame-Tage, sodass man durch wiederholtes Einsammeln das Inventar bis zum 240-Slot-Maximum ausbauen kann. Es ist also kein Einmal-Item.",loc:"Fundort: am Straßenrand zwischen Hernand und Demeniss, neben einem zerbrochenen Karren in den Hills of No Return; nächster Schnellreisepunkt Abyss-Nexus bei Karin-Quarry. Quelle: Game8, Gamer Guides, wccftech",miss:false,conf:"high",icon:"/assets/_sprites/itemicon_prefab_cd_t0000_inventorybag_0001.webp"},
  {name:"Fertilizer Sprayer",cat:"Werkzeug — Sammeln",detail:"Farm-Werkzeug, mit dem Dünger auf die Beete am Hof gesprüht wird, um Wachstum und Ernteertrag der Pflanzen zu steigern; es lassen sich mehrere Pflanzen auf einmal besprühen. Es ist ein dauerhaftes Werkzeug ohne Verschleiß und kann am Schmied nachgecraftet werden. Ergänzt sich mit dem Field Sprayer, mit dem zuvor bewässert wird.",loc:"Bezug: Belohnung aus der House-Celeste-Questreihe rund um die Abandoned-Factory-Story (Quest \"Foundation of Abundance\", Arboria Castle bei Hernand); danach am Schmied craftbar. Quelle: nerdschalk, The Games Wiki",miss:false,conf:"high",icon:"/assets/_sprites/itemicon_prefab_cd_phm_00_bag_0068.webp"},
  {name:"Field Pack",cat:"Werkzeug — Sammeln",detail:"Robuster Packen mit Ausrüstung und Feuermachwerkzeug. Im Spiel dient er nicht als Sammelwerkzeug, sondern als Crafting-Zutat: Basis-Packs wie das Field Pack werden für Kuku-Pack-Upgrades am Kuku-Topf benötigt (jeder Basis-Pack ist als Crafting-Basis austauschbar). Man sollte sie daher behalten und nicht verkaufen.",loc:"Verwendung: Crafting-Material für Kuku-Pack-Upgrades bei Grimnirs Kuku-Shop (Kuku-Topf). Basis-Packs respawnen u.a. an der Totesmith-Tannery bei Glenbright Farm. Quelle: Game8, GameRant, allthings.how",miss:false,conf:"high",icon:"cd_assets/items/field-pack.webp"},
  {name:"Field Sprayer",cat:"Werkzeug — Sammeln",detail:"Farm-Werkzeug zum Bewässern von Pflanzen; verkürzt die Wachstums- und Fruchtzeit. Hat eine Haltbarkeit und muss ersetzt werden (anders als Lubricant- und Fertilizer-Sprayer). Rezept durch Beobachten von Bauern in Demeniss. Quelle: VULKK (30.05.2026).",loc:"Crafting: 10 Fine Timber, 5 Iron Ore, 2 Copper Ore, 1 Rubber, 20 Water. Quelle: VULKK (30.05.2026).",miss:false,conf:"high",icon:"/assets/_sprites/itemicon_prefab_cd_phm_00_bag_0046.webp"},
  {name:"Fine Fishing Rod",cat:"Werkzeug — Sammeln",detail:"Stabile Angel aus haltbarem Material, deren Flexibilität dem Zug großer Fische standhält; erste echte Upgrade-Stufe über der einfachen Angelrute. Sie verkürzt die Wartezeit zwischen den Bissen.",loc:"Bezug: Bauplan (Fine Fishing Rod Blueprint) bei Grimrak im Back-Alley-Shop für 500 Kupfer (= 5 Silber; laut questlog auch bei Aegrin, Slywek, Thrak, Brek u. a.); fertige Rute laut questlog bei den Händlern Tranan und Varin für 3000 Kupfer (= 30 Silber). Die früheren Angaben 10 bzw. 45 Silber ließen sich nicht bestätigen. Crafting beim Schmied: 10x Fine Timber, 10x Iron Ore, 3x Thick Hide, 10x Feathers. Quelle: The Games Wiki, questlog.gg, crimsondesert.gaming.tools",miss:false,conf:"high",icon:"/assets/_sprites/itemicon_prefab_cd_t0000_fishingrod_0001_index01.webp"},
  {name:"Fishing Rod",cat:"Werkzeug — Sammeln",detail:"Basis-Angelrute. In-Game-Beschreibung (Game8/crimsondb, verbatim): \"For Catching Fish\". Grundwerkzeug fürs Angeln; aufgewertete Varianten (Fine Fishing Rod, Pororin Fishing Rod, The Claw) bilden die Angel-Werkzeugkette.",loc:"Kaufbar im Provisioner-Shop in Hernand (nahe Blummont Manor). Quelle: Game8, Fextralife, VULKK",miss:false,conf:"high",icon:"/assets/_sprites/itemicon_prefab_cd_t0000_fishingrod_0001.webp"},
  {name:"Heavy Bucket",cat:"Werkzeug — Sammeln",detail:"Ein robuster Eimer aus stabilem Metall oder Holz. Laut Item-Text langlebig und vor allem an anspruchsvollen Arbeitsstätten genutzt; fasst große Mengen Wasser oder Sand. Dient dem Transport bzw. Sammeln von Wasser oder Sand.",loc:"Allgemeines Arbeitswerkzeug; konkreter Vendor/Fundort in den Quellen nicht benannt (Basispreis laut Fextralife 15; kein Eintrag in den questlog-Spieldaten). Quelle: Fextralife, crimsondb.gg, crimsondesert.gaming.tools",miss:false,conf:"high",icon:"cd_assets/items/heavy-bucket.webp"},
  {name:"Hoe",cat:"Werkzeug — Sammeln",detail:"Rechtwinkliges Farm-Werkzeug zum Jäten von Feldern und zum Bearbeiten des Bodens. Es wird zum Auflockern der Erde, zum Ausgraben von Pflanzen und zur Pflege der Felder eingesetzt und eignet sich für Detailarbeit auf engem Raum. Nutzbar von Kliff und Oongka, beim Schmied bis +10 verbesserbar (Refinement).",loc:"Bezug: Farm-Werkzeug, beim Schmied per Refinement (Materialien + Währung) bis +10 verbesserbar. Quelle: Fextralife, crimsondesert.gaming.tools",miss:false,conf:"high",icon:"/assets/_sprites/itemicon_prefab_cd_t0000_hoe_0001.webp"},
  {name:"Insect Gatherer's Pack",cat:"Werkzeug — Sammeln",detail:"In-Game-Äquivalent eines Insekten-/Schmetterlingsnetzes (kein klassisches 'Net'-Item); im Spiel 'Kuku Insect Gatherer's Pack' (questlog 1000845). Fängt automatisch nahe Insekten ein; wird über das Funktionsrad mit L2+R2/LT+RT aktiviert, funktioniert auch in der Luft und beim Sprinten, Abklingzeit 10 Sekunden. Nötig u. a. für die Challenge 'Tiny Citizens of Grasslands' (76 Insekten, davon 49 Schmetterlinge).",loc:"Blueprint durch Reinigen des Sanctum of Oblation (nach Besuch bei Lyselia, Witch of Humility). Crafting bei Grimnir in der Kilden Workshop in Hernand (ab Kapitel 4): 1 Kuku Pack, 3 Abyss Cells, Power Core – Ore of Resipiscence, Power Core – Crown of Shadows. Quelle: GameRant, PowerPyx",miss:false,conf:"high",icon:"cd_assets/items/insect-gatherers-pack.webp"},
  {name:"Kuku Gardening Pack",cat:"Werkzeug — Sammeln",detail:"Sammel-Rucksack, der automatisch alle Pflanzen in der Umgebung fernerntet und ins Inventar legt; Abklingzeit 10 Sekunden. Wird aus einem Kuku Pack modifiziert (questlog-Rezept 'Kuku Plant Gatherer's Pack', Ergebnis-Item 'Kuku Gardening Pack'). Der Insect Gatherer's Pack wird ebenfalls aus einem Kuku Pack gefertigt, nicht aus diesem Rucksack.",loc:"Blueprint von Lyselia (Green Witch of Humility) durch Reinigen des Sanctum of Veneration am Mount Benus, Südost-Delesyia. Crafting bei Grimnir im Kilnden Workshop (westlich der Hauptstadt Hernand): 1 Kuku Pack, 3 Abyss Cells, Power Core – Ore of Resipiscence, Core of Mortification. Quelle: VULKK, TheGamer",miss:false,conf:"high",icon:"/assets/_sprites/itemicon_prefab_cd_phm_00_bag_0064.webp"},
  {name:"Large Farming Rake Scythe",cat:"Werkzeug — Sammeln",detail:"Eine Erntesense mit darüber montiertem Rechenaufsatz, der das geschnittene Getreide ordentlich auffängt. Vereint Schneiden und Einsammeln in einem Arbeitsgang und spart so Farm-Zeit. Am Schmied verfeinerbar.",loc:"Kaufbar bei Kikis Provisioner Shop im Demeniss-Territorium für 45 Münzen; Kiki im Hauptsiedlungsbereich aufsuchen. Quelle: nerdschalk, Fextralife, crimsondb.gg, questlog.gg, mapmaster.io",miss:false,conf:"high",icon:"/assets/_sprites/itemicon_prefab_cd_t0000_farmscythe_0003.webp"},
  {name:"Large Farming Scythe",cat:"Werkzeug — Sammeln",detail:"Große Sense mit langem Stiel, die im Stehen geschwungen wird, um Weizen oder Gras großflächig zu schneiden. Effizient für großflächige Arbeit zur Erntezeit. Beim Schmied über Refinement (Materialien + Währung) verbesserbar.",loc:"Bezug: Farm-/Ernte-Werkzeug, beim Schmied verbesserbar. Quelle: Fextralife, Gamer Guides, crimsondb.gg, questlog.gg",miss:false,conf:"high",icon:"/assets/_sprites/itemicon_prefab_cd_t0000_farmscythe_0001.webp"},
  {name:"Lubricant Sprayer",cat:"Werkzeug — Sammeln",detail:"Sprühgerät (Pack/Quickslot-Werkzeug), das Schmiermittel verteilt, um Reibung zwischen mechanischen Teilen zu verringern und Ausfälle zu verhindern. Wird aus dem Fernkampf-/Quickslot ausgerüstet, mit Sub-Attack gezielt und mit Heavy-Attack versprüht; hat begrenzte Haltbarkeit und muss danach neu gefertigt werden.",loc:"Fertigbar an der Schmiede (Kosten laut questlog-Rezept 1008763: 10 Fine Timber, 5 Iron Ore, 2 Copper Ore, 1 Rubber, 20 Water); das Rezept (zusammen mit Field Sprayer und Fertilizer Sprayer) wird laut Guides freigeschaltet, indem man auf dem Ackerland westlich von Demeniss einem Bauern beim Besprühen seiner Felder zusieht, bis die Spray-Animation abläuft. Quelle: Gamer Guides, VULKK, crimsondesert.app, questlog.gg",miss:false,conf:"high",icon:"/assets/_sprites/itemicon_prefab_cd_phm_00_bag_0070.webp"},
  {name:"Magic Scythe",cat:"Werkzeug — Sammeln",detail:"Verzauberte Sense: erntet Gras oder Feldfrüchte über einen größeren Bereich als eine normale Sense und leuchtet auf, wenn man sich nahe sammelbaren Pflanzen oder Insekten befindet. Der Effekt ist bis zu 3-mal aufladbar, mit 5 Sekunden Abklingzeit zwischen den Ladungen. (Effekt sowie Lade- und Cooldown-Werte von VULKK und crimsondb übereinstimmend bestätigt.)",loc:"Per Mission-Dispatch craftbar in Florindale nach Abschluss der Pororin-Forschung (Petalton Workshop, Lumiel-Forschungsbaum). Quelle: VULKK, crimsondb",miss:false,conf:"high",icon:"/assets/_sprites/itemicon_prefab_cd_t0000_farmscythe_0002.webp"},
  {name:"Mallet",cat:"Werkzeug — Sammeln",detail:"Holzhammer/Schlegel. In-Game-Beschreibung (Game8/crimsondb, verbatim): \"Used to Drive or Pound Nails\", zum Einschlagen von Nägeln. Utility-/Bauwerkzeug.",loc:"Kaufbar im Provisioner-Shop in Hernand (nahe Blummont Manor). Quelle: Game8, Fextralife",miss:false,conf:"high",icon:"/assets/_sprites/itemicon_prefab_cd_t0000_hammer_0003.webp"},
  {name:"Peddler's Pack",cat:"Werkzeug — Sammeln",detail:"Trage-/Transport-Pack (Rucksack) zum Befördern von Waren, Materialien und Handelsgütern. Dient als Material, um den Kuku Pack herzustellen, der wiederum für den Kuku Rocket Pack von Oongka benötigt wird.",loc:"Käuflich für 85 Kupfer direkt hinter dem Händler an der Totesmith Tannery (südwestlich des Hernand Highlands); weitere Exemplare im Umfeld sind nicht käuflich, lassen sich aber mit angelegter Maske stehlen. Die Packs respawnen, wenn man das Gebiet verlässt und zurückkehrt. Quelle: Game8, TheGamer, GameRant, nerdschalk",miss:false,conf:"high",icons:["cd_assets/items/peddlers-pack-1.webp","cd_assets/items/peddlers-pack-2.webp","cd_assets/items/peddlers-pack-3.webp"]},
  {name:"Pitchfork",cat:"Werkzeug — Sammeln",detail:"Heugabel, mit der Erde zum Bestellen der Felder umgegraben oder Kompost, Stroh und ähnliches Material aufgespießt und bewegt wird. An jeder Schmiede per Refinement aufwertbar.",loc:"Bei jedem Provisioner-Vendor in den Städten von Pywel kaufbar. Quelle: Fextralife (Tools), Gamer Guides, PowerPyx",miss:false,conf:"high",icon:"/assets/_sprites/itemicon_prefab_cd_t0000_hayfork_0001.webp"},
  {name:"Pororin Fishing Rod",cat:"Werkzeug — Sammeln",detail:"Leichte und dennoch robuste Angelrute aus Spinnenseide, gefertigt von einem Handwerker im Arboria Craftshop nach einer in Pororin überlieferten Technik. Bietet Fishing-Cooldown-Reduction Lv 2 und ist darauf ausgelegt, jeden Fisch zu fangen — die empfohlene Rute für seltene, große und legendäre Fische.",loc:"Freigeschaltet über das Forschungsprojekt 'Secret Tools of Life' (Projekt 2C) im Pororin-Forschungsbaum (Kosten 500 Silber, Dauer 1 Tag 4 Std. — Stand vor Patch 1.18.00; dieser Patch hat am 15.08.2026 die für Forschung benötigte Ressource von Silber auf Camp-Mittel umgestellt, ohne einen Betrag oder Umrechnungskurs zu nennen, der Zahlenwert steht damit unter Vorbehalt); die Rute selbst wird danach über die Produktions-/Dispatch-Option des Arboria Craftshop gefertigt. Quelle: Fextralife, Gamer Guides, crimsondb.gg, gaming.tools",miss:false,conf:"high",icon:"/assets/_sprites/itemicon_prefab_cd_t0000_fishingrod_0002.webp"},
  {name:"Rake",cat:"Werkzeug — Sammeln",detail:"Rechen zum Einebnen der Feld-Erde oder zum Entfernen von Kies; gut geeignet, um den Boden zu glätten. An einer Schmiede per Refinement aufwertbar.",loc:"Bei jedem Provisioner-Vendor in Pywel kaufbar, u. a. im Provisioner's Shop der ersten Stadt Hernand (die Straße hinunter nahe Blummont Manor, gegenüber den Equipment- und Tailor-Shops), wo auch Fishing Rod, Shovel und Mallet verkauft werden. Quelle: Fextralife, VULKK, gaming.tools",miss:false,conf:"high",icon:"/assets/_sprites/itemicon_prefab_cd_t0000_rake_0001.webp"},
  {name:"Saw",cat:"Werkzeug — Sammeln",detail:"Ein Schneidwerkzeug mit scharfen Zähnen. Laut Item-Text dient es dazu, Holz auf Maß zu schneiden oder Planken/Bretter zu verarbeiten. Am Schmied per Refinement verbesserbar (sichtbar an goldenen Linien im Item-Bild).",loc:"Allgemeines Holzbearbeitungs-/Sammelwerkzeug; konkreter Vendor/Fundort in den Quellen nicht benannt (Basispreis laut Fextralife 34; kein Eintrag in den questlog-Spieldaten). Quelle: Fextralife, crimsondesert.gg, crimsondesert.gaming.tools",miss:false,conf:"high",icon:"cd_assets/items/saw.webp"},
  {name:"Shovel",cat:"Werkzeug — Sammeln",detail:"Grabwerkzeug zum Ausheben von Erde oder Sand. In-Game-Beschreibung (Fextralife, verbatim): \"A tool for digging up soil or sand. The wide blade can be pressed down with a foot to dig deeper.\" Deckt vergrabene Gegenstände auf (Game8: \"Uncovers Buried Items\") und wird vor allem für das späte Skyroot-Graben benötigt. Basis-Angriff 6.",loc:"Kaufbar im Provisioner-Shop in Hernand (nahe Blummont Manor). Quelle: Fextralife, Game8",miss:false,conf:"high",icon:"/assets/_sprites/itemicon_prefab_cd_t0000_shovel_0001.webp"},
  {name:"Small Bag",cat:"Werkzeug — Sammeln",detail:"Kein Sammel-/Farmwerkzeug, sondern ein Inventarerweiterungs-Item: schaltet 1 zusätzlichen Inventarplatz frei. Aktiviert sich automatisch beim Erhalt, kein manuelles Ausrüsten nötig. Günstigste Form des permanenten Inventar-Upgrades.",loc:"Nahezu jeder Händler in Pywel führt genau einen Small Bag für ca. 50 Kupfer (kein Nachschub nach dem Kauf); zusätzlich als Belohnung einiger früher Quests/Nebenaufgaben. Quelle: GameSpot, Fextralife, games.gg, thegameswiki",miss:false,conf:"high",icon:"/assets/_sprites/itemicon_prefab_cd_t0000_inventorybag_0003.webp"},
  {name:"Sotdae of Bond",cat:"Werkzeug — Sammeln",detail:"Vogel-Futterstation (Bird Feeder), das zentrale Mittel zum Zähmen von Vögeln. Wird in der Wildnis platziert (Strg+R bzw. LB+Y); nach dem Befüllen landet ein Vogel und frisst, bis seine Trust-Anzeige 100 erreicht und er sich als Haustier aufnehmen lässt. Verschiedene Umgebungen locken verschiedene Vögel an (Berg: Adler/Sperber; Fluss: Krähe/Sperling). Mit einem Update zusammen mit den Vogel-Haustieren hinzugefügt.",loc:"Belohnung für den Abschnitt 'Authorized Access' der Fraktionsquest 'Trembling Woods' für die Pororin Forest Guardians; die Questreihe wird beim Betreten des Dorfes Florindale (südöstlich des Hernand Highlands) ausgelöst, wo man per Schlafpfeil betäubt und dem Wächter Arkin vorgestellt wird. Quelle: PC Gamer, Shacknews, KeenGamer, GAMES.GG",miss:false,conf:"high",icon:"/assets/_sprites/itemicon_cd_item_gimmick_birdfeeder_0001.webp"},
  {name:"The Claw",cat:"Werkzeug — Sammeln",detail:"Eine einzigartig benannte Angelrute mit Auto-Fishing-Funktion: Statt manuell einzuholen (rechter Stick), genügt ein einzelner Tastendruck, um gehakte und ermüdete Fische selbsttätig einzuziehen. Macht das ansonsten knifflige Angeln deutlich einfacher.",loc:"Verfügbar ab Abschluss von Kapitel 3. Zwei Wege: Patrigios 'Trust' auf 100 bringen (er erscheint als wandernder Geheimhändler nachts zwischen 0 und 3 Uhr nahe dem Howling-Hill-Camp; Vertrauen steigt durch Schenken von ca. 20 Kupferbeuteln, deren Wert egal ist), oder Stehlen von einem Fischer am Steg in Bounty's Net (südwestlich der Spire of Insight, bzw. ein Fischerdorf südlich von Hernand westlich der Steel Mountains). Quelle: TheGamer, Sportskeeda, GameRant, games.gg",miss:false,conf:"high",icon:"/assets/_sprites/itemicon_prefab_cd_t0000_fishingrod_0003.webp"},
  {name:"Wooden Pitchfork",cat:"Werkzeug — Sammeln",detail:"Heugabel aus Holz, ein Werkzeug vom Rechen-Typ mit Angriffswert 31. Sie ist leichter als eine Eisengabel und eignet sich gut, um große Mengen Heu zu tragen, kann aber nicht auf hartem Boden eingesetzt werden. Wie alle Werkzeuge nur ein schwacher Notbehelf im Kampf.",loc:"Wird als Farmwerkzeug genutzt und über Werkzeughändler bzw. Feldarbeit bezogen; interner Datenbank-Slug equip_trirake. Quelle: Gamer Guides, crimsondesert.gaming.tools, Fextralife Tools",miss:false,conf:"high",icon:"/assets/_sprites/itemicon_prefab_cd_t0000_rake_0003.webp"},
  {name:"Wooden Rake",cat:"Werkzeug — Sammeln",detail:"Ein leichter Holzrechen. Laut Item-Text zum Zusammenrechen von Falllaub oder zum Aufräumen von geschnittenem Gras gedacht; nicht geeignet, um tief in den Boden zu graben. Von jedem Charakter nutzbar, am Schmied bis +10 verfeinerbar (Angriff bis 31).",loc:"Bei einem Händler nahe Blummont Manor erhältlich (die Straße hinunter von der zentralen Taverne). Quelle: Fextralife, crimsondesert.gaming.tools, crimsondesert.app, Game8 (Tools-Liste, archive 586917)",miss:false,conf:"high",icon:"/assets/_sprites/itemicon_prefab_cd_t0000_rake_0002.webp"},
  {name:"Wide Basket",cat:"Werkzeug — Sammeln",detail:"Korb-/Tragewerkzeug aus der Tools-Kategorie, das zum Sammeln und Transportieren von Erntegut bzw. Materialien dient. Es zählt zu den Alltags- und Farmwerkzeugen und richtet im Kampf kaum Schaden an. Eine eigene Statwerttabelle ist in den Quellen nicht hinterlegt.",loc:"Wird wie andere Sammel- und Tragewerkzeuge über Werkzeughändler bezogen und kann bei Schmieden in den Städten verfeinert werden; die genaue Fundstelle ist nicht dokumentiert. Quelle: Fextralife Tools, crimsondb.gg Tools",miss:false,conf:"medium",icon:"cd_assets/items/wide-basket.webp"},
  {name:"Kuku Pot",cat:"Werkzeug — Erkundung",detail:"Zwergisches Speicher-/Crafting-Gerät mit 230 Slots, das nur Abyss-Objekte, Maschinenteile und Crafting-Komponenten aufnimmt (keine Waffen, Rüstung oder Nahrung). Basis eines tiefen Progressionssystems: Am Pot lassen sich einzigartige Ausrüstung, Utility-Packs/Rucksäcke, Elementar-Rüstungssets und Komponenten herstellen. Jedes Kuku-Upgrade verlangt einen weiteren Kuku Pot als Zutat; alle Pots teilen dasselbe Inventar. Enhanced Kuku Pot = 1 Kuku Pot + 1 Abyss Cell, schaltet höhere Rezepte bei Grimnir frei. Stark mit dem Abyss-/Synthese-System verzahnt (Grenzfall — ggf. eigener Tab).",loc:"Erhalt in Kapitel 4 über die Hauptquest \"Mysterious Pot\": führt zum Kilnden Workshop westlich von Hernand, beim Zwerg Grimnir (zuvor dessen Werkstatt/Kilns reparieren). Quelle: method.gg, GameSpot, VULKK",miss:false,conf:"high",icon:"/assets/_sprites/itemicon_item_kuku_pot_empty.webp"},
  {name:"Visione",cat:"Werkzeug — Erkundung",detail:"Kopfbedeckung mit Erkundungs- und Narrativfunktion statt Kampfschutz: liest Memory Fragments und lässt den Träger Blicke in die Vergangenheit sehen. Zusammen mit der pulsierenden Laterne werden die weltweit verteilten Memory Fragments aufgespürt und abgespielt. Technisch als Headgear/Rüstung geführt (Grenzfall zum Rüstungs-Tab). Cosmetic-Alternativversionen sollen nach Abschluss der Delesyian-Institute-Forschung erhältlich sein (nicht unabhängig bestätigt).",loc:"Im obersten Stockwerk des Lioncrest Watchtower (nach Säubern des Banditenlagers) während Kapitel 2 der Hauptquest \"Unexpected Gift\" (Teilziel/Memory-Fragment-Strang \"Where the Light Leads\"). Quelle: Fextralife, Game8, PowerPyx",miss:false,conf:"high",icon:"/assets/_sprites/itemicon_prefab_cd_phm_00_hel_00_0354_c.webp"},
  {name:"Whistle",cat:"Werkzeug — Mount",detail:"Pfeif-Gadget zum Herbeirufen des Reittiers: per Tastendruck (D-Pad hoch / Taste H) pfeift die Figur, und das Pferd erscheint am nächsten geeigneten Punkt hinter dem Spieler. Frühes Aufwerten der Pfeife vergrößert die Rufreichweite und macht sie zu einer der zentralen Erkundungshilfen, um Pywel schnell zu durchqueren. Funktion/Feature, kein klassisches Inventar-Item (Grenzfall).",loc:"Standardfähigkeit ab Spielbeginn; Reichweiten-Upgrades über Spielfortschritt/Stall. Quelle: Shacknews, esports.gg",miss:false,conf:"medium"},
  {name:"Arrow",cat:"Munition",detail:"Standard-Pfeilmunition für Bögen, um Ziele aus der Distanz in Jagd oder Kampf zu treffen. Grundmunition ohne Sondereffekt.",loc:"Equipment-/Waffenhändler, Smithy-Crafting, Gegner-Loot; basaler Resupply u. a. am Calphade Siege Armory. Quelle: Fextralife Projectiles, crimsondb.gg",miss:false,conf:"high",icon:"/assets/_sprites/itemicon_prefab_cd_phm_04_arw_0001.webp"},
  {name:"Blitz Arrow (Lightning Arrow)",cat:"Munition",detail:"Pfeil, um Ziele aus der Ferne zu treffen und Blitz-/Lightning-Schaden zuzufügen.",loc:"Belohnung der Mission „Camel Constellation“ (Quest „Constellations“; im questlog-Item 1001315 als Schritt „Observe the camel constellation“ geführt, dort unter Sammelgegenständen statt unter Projektilen); Slug lightning_arrow / blitz-arrow. Quelle: questlog.gg, crimsondesert.gaming.tools, crimsondb.gg",miss:false,conf:"high",icon:"/assets/_sprites/itemicon_prefab_cd_phm_04_arw_0018.webp"},
  {name:"Bullet",cat:"Munition",detail:"Metallkugel, mit Schwarzpulver verschossen; jeder Schuss verbraucht viel Pulver, daher seltener nutzbar als Pfeile. Munition für Pistole, Muskete und Schrotflinte.",loc:"Bei Händlern für 3 Kupfer kaufbar (questlog: zahlreiche Händler, z. B. Rhett, Temir, Kathor); Craft am Blacksmith aus 2 Iron Ore + 4 Gunpowder; Loot von Schützen, Versorgungskisten in Pywel. Quelle: questlog.gg, Fextralife Bullet, crimsondb.gg",miss:false,conf:"high",icon:"/assets/_sprites/itemicon_prefab_cd_t0254_dropitem_bullet_0001.webp"},
  {name:"Explosive Arrow (Bomb Arrow)",cat:"Munition",detail:"Pfeil mit Sprengvorrichtung, der bei Aufprall explodiert; deutlicher Flächenschaden gegen Gegnergruppen, schwache Strukturen oder als harter Einzeltreffer.",loc:"Freischaltung über die Demeniss-Armory-Dispatch-Mission (alle 12 Ingame-Stunden), zusätzlich bei Back-Alley-Händlern kaufbar. Quelle: itemlevel.net, Sportskeeda",miss:false,conf:"high",icon:"/assets/_sprites/itemicon_prefab_cd_phm_04_arw_0007.webp"},
  {name:"Ice Arrow (Chill Arrow)",cat:"Munition",detail:"Pfeil mit Eis-/Frost-Element; trifft Ziele aus der Distanz und fügt Eisschaden zu. Ingame-/Datenbankname lautet \"Chill Arrow\" (Slug ice_arrow).",loc:"Belohnung der Mission „Elephant Constellation“ (Quest „Constellations“; im questlog-Item 1001314 „Chill Arrow“ als Schritt „Observe the elephant constellation“ geführt, dort unter Sammelgegenständen); Slug ice_arrow / chill-arrow. Quelle: questlog.gg, crimsondesert.gaming.tools, crimsondb.gg",miss:false,conf:"high",icon:"/assets/_sprites/itemicon_prefab_cd_phm_04_arw_0016.webp"},
  {name:"Poison Arrow",cat:"Munition",detail:"Pfeil, der beim Treffer Gift (Schaden über Zeit) auslöst; gut zum Anstacken von Dauerschaden, besonders gegen zähe Gegner.",loc:"Rezept im Back Alley Shop von Fort Perwin kaufbar; Craft aus 1 Pfeil + 1 Giftflasche (Gift u. a. beim Häuten von Waranen/Monitor Lizards). Quelle: itemlevel.net, Sportskeeda",miss:false,conf:"high",icon:"/assets/_sprites/itemicon_prefab_cd_phm_04_arw_0008.webp"},
  {name:"Replenishing Bullets",cat:"Munition",detail:"Schwarzpulver-Kugeln, die sich durch fortschrittliche Technik mit der Zeit selbst nachfüllen (begrenzter Vorrat von ca. 40, der langsam regeneriert); Munition für Pistole, Muskete und Schrotflinte.",loc:"Freischaltung über die Keep-Facility-Forschung im Dohaven Research Institute, Ausbau via Electric Tool Design u. a. Quelle: crimsondb.gg, crimsondesert.gaming.tools",miss:false,conf:"high",icon:"/assets/_sprites/itemicon_prefab_cd_t0254_dropitem_bullet_0001_infinite.webp"},
  {name:"Sleep Arrow",cat:"Munition",detail:"Pfeil mit beruhigungsmittelbeschichteter Spitze; das getroffene Ziel fällt in Schlaf/Bewusstlosigkeit und schafft ein taktisches Fenster für Folgeangriffe.",loc:"Beim Stamm in Longleaf Village: Longbranch-Tribe-Rätsel lösen und Vertrauen aufbauen, danach im Versorgungsdepot abrufbar. Quelle: Sportskeeda, itemlevel.net",miss:false,conf:"high",icon:"/assets/_sprites/itemicon_prefab_cd_phm_04_arw_0014.webp"},
  {name:"Small Cannonball",cat:"Munition",detail:"Kleinkalibrige, leicht transportierbare Kanonenkugel, dicht mit Schwarzpulver gepackt; löst beim Aufprall eine Explosion mit Schockwelle aus, die nahe Gegner wegschleudert und Formationen zerbricht. Munition für Hand Cannons.",loc:"Craft am Smithy aus 10 Iron Ore + 10 Gunpowder (Rezept). Quelle: Fextralife (Small Cannon Ball Recipe), crimsondesert.gaming.tools",miss:false,conf:"high",icon:"/assets/_sprites/itemicon_prefab_cd_t0254_dropitem_cannonball_0001.webp"},
  {name:"Stub Arrow (Pyeonjeon Arrow)",cat:"Munition",detail:"Spezialpfeil in kürzerer, schlankerer Form als Standardpfeile; liefert Durchschlags- und Zerstörungskraft, die gewöhnliche Pfeile übertrifft.",loc:"In Datenbanken geführt (Slug pyeonjeon_arrow / stub-arrow). Quelle: crimsondesert.gaming.tools, crimsondesert.gg",miss:false,conf:"high",icon:"/assets/_sprites/itemicon_prefab_cd_phm_04_arw_0020.webp"},
  {name:"Whistling Arrow (Hyosi Arrow)",cat:"Munition",detail:"Signalpfeil zum Herbeirufen verbündeter Unterstützung; auf den Boden geschossen, ruft er ein Artillerie-Sperrfeuer auf das Zielgebiet. Die eigene Durchschlagskraft ist kaum höher als bei einem normalen Pfeil.",loc:"In Datenbanken geführt (Slug hyosi_arrow / whistling-arrow). Quelle: crimsondesert.gaming.tools, crimsondb.gg",miss:false,conf:"high",icon:"/assets/_sprites/itemicon_prefab_cd_phm_04_arw_0003.webp"},
  {name:"Crude Bismuth Cannonball",cat:"Munition",detail:"Kanonenkugel-Munition aus Bismut, die einfache (rohe) Unterstufe der Bismut-Geschosslinie. Sie wird für tragbare Kanonen bzw. die Bismut-Kanone verwendet und liefert flächigen Explosionsschaden. Höherwertige Varianten ohne den 'Crude'-Zusatz haben bessere Werte; die Reihe umfasst u. a. auch Crude Itano und Itano Cannonball.",loc:"Laut questlog Zufallsdrop bei Demenissian Guard und Belohnung der Dispatch-Mission „St. Halssius's House of Healing Bridge Construction“; ein Herstellungsrezept für diese Kugel führt questlog nicht, die Guide-Angabe „über Bismut hergestellt“ ist damit nicht bestätigt (Bismut ist laut Guides erst nach Freischalten einer Blitzfähigkeit abbaubar: Damiane Kap. 3 bzw. Kliffs Blitzbogen Kap. 4). Quelle: questlog.gg (1000018), Gamer Guides (Projektilliste), thegameswiki Cannons-Guide, crimsondb.gg Ammunition",miss:false,conf:"medium",icon:"/assets/_sprites/itemicon_prefab_cd_t0254_dropitem_cannonball_0001.webp"},
  {name:"Dark Magic Bullet",cat:"Munition",detail:"Magische Wurf-/Schuss-Kugel mit Dunkelheits-Element (\"A Magic Bullet for Throwing - Darkness\").",loc:"Listeneintrag crimsondb.gg (dark-magic-bullet). Quelle: crimsondb.gg",miss:false,conf:"medium",icon:"/assets/_sprites/itemicon_prefab_cd_t0254_dropitem_bullet_0001.webp"},
  {name:"Disruptor Cannonball",cat:"Munition",detail:"Anti-Maschinen-Kanonenkugel, die auf Stör-/Unterbrechungsnutzen statt auf rohen Schaden ausgelegt ist: Trifft sie einen mechanischen Gegner, unterbricht sie dessen Energiefluss und setzt ihn vorübergehend außer Gefecht (questlog; Einsatz mit dem Blaster). Sie wird empfohlen für schwierige Gefechte und Bosskämpfe aufzusparen. Bezug laut questlog: Belohnung der Mission „True Strength“ (Quest „Six Statues and the Beast“; im Item-Datensatz als Schritt „Guide T'rukan onto the righteous path“ geführt).",loc:"Spezialmunition für Kanonen; Bezug über Crafting bzw. Munitionsvorräte. Quelle: thegameswiki Cannons-Guide, crimsondb.gg Ammunition, crimsondesert.gg Ammo",miss:false,conf:"medium",icon:"/assets/_sprites/itemicon_prefab_cd_phm_10_bomb_0010.webp"},
  {name:"Fire Arrow",cat:"Munition",detail:"Pfeil mit Feuerelement (Feuerschaden aus der Distanz). Item-Text: 'can also deal fire damage'. Das Item existiert in den Spieldaten (questlog 1001316), allerdings in der Kategorie collectibles/goods (Grundwert 2 Kupfer) und nicht als Munition (projectiles) wie Bullet; einzelne Guides sagen dagegen, es gebe keine Feuerpfeil-Munition und Feuerschaden entstehe nur durch Entzünden eines normalen Pfeils an Lagerfeuer/Fackel. Ob das Item als normale Munition nutzbar ist, ist nicht belegt.",loc:"Questlog nennt als Herkunft die Mission 'Observe the goblin constellation'; Listeneintrag auch bei crimsondesert.gaming.tools (fire_arrow); alternativ Entzünden normaler Pfeile an Feuerquellen. Quelle: questlog.gg (Item 1001316), crimsondesert.gaming.tools, Sportskeeda",miss:false,conf:"medium",icon:"/assets/_sprites/itemicon_prefab_cd_phm_04_arw_0012.webp"},
  {name:"Itano Cannonball",cat:"Munition",detail:"Kanonenkugel, die einen spezialisierten Sprengsatz freisetzt, der mit erratischen Hochgeschwindigkeits-Manövern Gegner aufspürt (zielsuchend/Homing). Munition für Hand Cannons.",loc:"Listeneintrag crimsondb.gg (itano-cannonball). Quelle: crimsondb.gg",miss:false,conf:"medium",icon:"/assets/_sprites/itemicon_prefab_cd_t0254_dropitem_cannonball_0001.webp"},
  {name:"Magic Bullet",cat:"Munition",detail:"Magische Wurf-/Schuss-Kugel mit Wind-Element (\"A Magic Bullet for Throwing - Wind\").",loc:"Listeneintrag crimsondb.gg (magic-bullet). Quelle: crimsondb.gg",miss:false,conf:"medium",icon:"/assets/_sprites/itemicon_prefab_cd_t0254_dropitem_bullet_0001.webp"},
  {name:"Mine Spider Cannonball",cat:"Munition",detail:"Spezial-Kanonenkugel mit Zusatznutzen über reinen Schaden hinaus; ebenfalls für schwierige Kämpfe und Bosse gedacht. Die Kugel beschwört eine Minenspinne, die Gegner aufspürt, eine starke Explosion auslöst und alle Gegner in der Nähe wegschleudert (questlog).",loc:"Spezialmunition für Kanonen; Bezug über Crafting bzw. Munitionsvorräte. Quelle: thegameswiki Cannons-Guide, crimsondb.gg Ammunition, crimsondesert.gg Ammo",miss:false,conf:"medium",icon:"/assets/_sprites/itemicon_prefab_cd_t0254_dropitem_cannonball_0001.webp"},
  {name:"Replenishing Arrows (Quiver)",cat:"Munition",detail:"Pfeil-Munition mit verbessertem Aufbau; laut Item-Text (questlog) lassen sich zerbrochene Pfeile wiederverwenden ('allows broken arrows to be reused'). Guides beschreiben es als Köcher-/Versorgungs-Item, das den Pfeilvorrat mit der Zeit selbsttätig nachfüllt (Slug quiver bei crimsondesert.gaming.tools); der Item-Text nennt das – anders als bei den 'Replenishing Bullets' ('self-replenish over time') – nicht.",loc:"Questlog (Item 1002557, DE 'Pfeil: Stetiger Nachschub') nennt als Herkunft die Mission 'Restore the Abyss' (Quest 'The Abyss'); thematisch verwandt mit den \"Infinite Arrows\"-Abyss-Gear. Quelle: questlog.gg, crimsondesert.gaming.tools, TheGamer",miss:false,conf:"medium",icon:"/assets/_sprites/itemicon_prefab_cd_phm_04_arw_0001_infinite.webp"},
  {name:"Fire Bomb",cat:"Verbrauchsgegenstand — Wurf/Kampf",detail:"Wurfwaffe, die mit Schwarzpulver eine kraftvolle Explosion und Feuer erzeugt; nach dem Zünden auf ein Ziel werfbar oder am Boden als Falle platzierbar.",loc:"Craftbar über Alchemie/Engineering oder bei Spezialhändlern kaufbar; Datenbank-Slug fire_bomb. Quelle: crimsondesert.gaming.tools, crimsondesert.gg",miss:false,conf:"high",icon:"cd_assets/items/fire-bomb.webp"},
  {name:"Smoke Bomb",cat:"Verbrauchsgegenstand — Wurf/Kampf",detail:"Umhüllt den Explosionspunkt mit Rauch und bricht die Sichtlinie der Gegner; Kernwerkzeug für Stealth (Entkommen/Verschwinden), gekoppelt an die Storm-Veil-Fähigkeit.",loc:"Fähigkeit/Abruf wird laut Guides über den Hauptstrang ab Abschluss von Kapitel 8 (Spire of Clockwork / Abyss) freigeschaltet; das Item selbst ist laut questlog bei Händlern für 70 Kupfer kaufbar (z. B. Bran, Leonard, Marin; Item 1000803) und Belohnung einer Abyss-Mission 'Restore the Abyss'. Datenbank-Slug smoke_bomb. Quelle: questlog.gg, crimsondesert.gaming.tools, GamerGuides",miss:false,conf:"high",icon:"cd_assets/items/smoke-bomb.webp"},
  {name:"Vine Bomb",cat:"Verbrauchsgegenstand — Wurf/Kampf",detail:"Wurfbombe. Beim Explodieren werden die im Wirkungsbereich erfassten Gegner in Ranken gefangen und dadurch bewegungsunfähig gemacht (Fang-/Verwurzelungseffekt statt reinem Schaden).",loc:"Eigene Datenbankseite sowie Munitionslisten; Effekt mehrfach beschrieben. Quelle: crimsondb.gg, questlog.gg, crimsondesert.gg",miss:false,conf:"high",icon:"cd_assets/items/smoke-bomb.webp"},
  {name:"Crow Bomb",cat:"Verbrauchsgegenstand — Wurf/Kampf",detail:"Wurfbombe, die bei der Explosion einen Schwarm Krähen beschwört. Die Krähen greifen nahe Gegner an.",loc:"Munitionsdatenbanken; die aktuelle Itembeschreibung bestätigt die Krähenwirkung. Quelle: questlog.gg, crimsondb.gg",miss:false,conf:"high"},
  {name:"Water Bomb",cat:"Verbrauchsgegenstand — Wurf/Kampf",detail:"Wurfbombe, die am Aufprallpunkt Wassertropfen erzeugt und getroffene Gegner darin einschließt.",loc:"Munitionsdatenbanken; die aktuelle Itembeschreibung bestätigt den Fangeffekt. Quelle: questlog.gg, crimsondb.gg",miss:false,conf:"high"},
  {name:"Antidote",cat:"Verbrauchsgegenstand — Heilung/Status",detail:"Verbrauchsgegenstand, der den Gift-Status (Poison-DoT) heilt. Weder in den Spieldaten von questlog noch auf Fextralife findet sich ein Item namens 'Antidote' oder ein anderer Verbrauchsgegenstand, der Gift heilt; Existenz und Wirkung sind unbestätigt (Prüfung 03.10.2026).",loc:"Datenbank-/Listeneintrag (Game8, crimsondb.gg). Quelle: Game8 List of All Items, crimsondb.gg",miss:false,conf:"low"},
  {name:"Abyss Artifact",cat:"Währung & Progression",detail:"Kern-Progressionswährung, ersetzt das klassische XP-Leveln. Ein reguläres Artefakt gewährt sofort 1 Skill Point für den Skill-Tree oder für Kernwerte (Health, Spirit, Stamina). Ab Equipment-Refinement +5 werden zusätzlich reguläre Abyss Artifacts zum Aufwerten von Waffen/Rüstung benötigt; in Gear investierte Artefakte sind nicht rückholbar (auch nicht per Faded). Von egamersworld, esports.gg und GamesGG bestätigt.",loc:"Welt-Drops, Bosse, Erkundung, Belohnung aus Sealed Abyss Artifacts. Käuflich laut questlog für 2850 Kupfer bei den Hexen Areciel, Elowen, Bari und Lyselia sowie bei Patrigio; Jasper verkauft es gegen 200 Marni Token. Quelle: questlog.gg (Item 75001), egamersworld, esports.gg, GamesGG",miss:false,conf:"high",icon:"/assets/_sprites/itemicon_prefab_cd_t0000_abyss_artifact_a_0001.webp"},
  {name:"Camp Funds",cat:"Währung & Progression",detail:"Gemeinschaftswährung getrennt vom persönlichen Silver, finanziert das Greymane Camp: Dispatch-Missionen, Ausbauten und das Pailune-Wiederaufbauprojekt. Verdient durch Spende an Carl (Provisions Keeper) am Howling Hill via 'Manage Provisions' > 'Camp Provisions' > 'Donate Funds' (persönliches Silver oder laut älteren Guides Gold Bars; seit Patch 2.01.00 vom 04.09.2026 bringt gespendetes Silver die zehnfache Menge Camp Funds; ob Gold Bars danach noch am schnellsten sind, ist offen, questlog nennt als Quellen nur Silberspenden und Entsendungen) oder durch Greymane-Dispatch auf 'Shield'/Security-Missionen bei Ross (Dispatch-Koordinator), die Camp Funds geben und wiederholbar sind.",loc:"Spende an Carl (Howling Hill) oder Dispatch-Belohnungen über Ross. Quelle: GameRant, Game8, gfinityesports",miss:false,conf:"high",icon:"/assets/_sprites/itemicon_prefab_cd_t0056_coin_0004.webp"},
  {name:"Coin Purse",cat:"Währung & Progression",detail:"Von Gegnern gedroppte Geldbörse (Sammelbegriff; questlog führt die Beutel einzeln: Paltry/Light/Modest/Full Copper Pouch, Modest/Full/Overflowing/Wayfarer's Silver Pouch). Kein Verkaufs-Item, sondern direkt aus dem Inventar zu öffnen und sofort in Silber umgewandelt. Quelle: PowerPyx.",loc:"Gegner-Loot. Quelle: PowerPyx.",miss:false,conf:"medium",icon:"cd_assets/items/coin-purse.webp"},
  {name:"Contribution Point",cat:"Währung & Progression",detail:"Regional gebundene Fraktions-Währung (getrennt von der globalen Reputation); in den Spieldaten je Region als 'Hernand-, Demeniss-, Pailune-, Delesyia-, Tashkalp-Beitrag' bzw. 'Graumähnen-Beitrag' geführt (EN: Hernandian/Demenissian/Pailunese/Delesyian/Tashkalp/Greymane Contribution). Contribution-XP stammen aus Fraktionsquests, Notice-Board-Requests, Bounties und guten Taten (Flüchtlinge befreien, Bettlern Münzen geben); das Befreien von Festungen gibt den größten Einzel-Schub. Pro Level 1 Contribution Point. Ausgegeben in regionalen Contribution Shops für exklusive Gear, Accessoires, Horse Bardings, Banner (als Zweihandwaffe nutzbar) und Camp-Worker. Gekaufte Items sind zum gleichen Punktpreis rückverkaufbar. Diebstahl senkt die Contribution.",loc:"Fraktionsquests/Bounties je Region; Ausgabe in regionalen Contribution Shops (z. B. Haldwin in Hernand Castle). Quelle: GameRant, PC Gamer, Game8",miss:false,conf:"high"},
  {name:"Copper Coin",cat:"Währung & Progression",detail:"Kleinste Währungseinheit und häufigster Gegner-Drop, auch aus Beute-Beuteln (Copper/Silver Pouch). Für kleine Käufe wie Schlüssel (z.B. 30 Copper beim Back Alley Merchant). Umrechnung: 100 Copper = 1 Silver. Im Spiel als 'Copper' geführt (questlog Item 1). Mehrfach bestätigt (Method.gg, PowerPyx, thegameswiki).",loc:"Gegner-Drops, Beutel, Erkundung in ganz Pywel. Quelle: Method.gg, PowerPyx, thegameswiki",miss:false,conf:"high",icon:"cd_assets/items/copper-coin.webp"},
  {name:"Crude Gold Bar",cat:"Währung & Progression",detail:"Roh-Goldbarren als sammelbare Verkaufswährung (Patch 1.05.00). An Händler in Pywel ~5 Silber/Stück; Wolfram (Fischshop, Vellua) zahlt 7,90 Silber. In großen Clustern (100-200 Stück) an einzelnen Fundorten farmbar. Quelle: PC Gamer / Game8.",loc:"Sammelbare Cluster über Pywel verteilt; Verkauf an Händler/Wolfram. Quelle: PC Gamer.",miss:false,conf:"high",icon:"/assets/_sprites/itemicon_prefab_cd_in_dpfo_goldbar_01.webp"},
  {name:"Faded Abyss Artifact",cat:"Währung & Progression",detail:"Respec-Währung: Der Verbrauch setzt den kompletten Skill-Tree zurück und gibt alle in Skills investierten Punkte zur Neuverteilung frei; laut Item-Text lassen sich auch in Stamina, Spirit und Health investierte Abyss-Kräfte zurückholen. Setzt jedoch KEINE in Gear-Refinement investierten Artefakte zurück. Wichtig: betrifft alle drei spielbaren Charaktere (Kliff, Damiane, Oongka) gleichzeitig, da sie denselben Artefakt-Pool teilen. Laut VULKK existiert eine Methode, faktisch unbegrenzt Faded Abyss Artifacts zu farmen.",loc:"Welt-Drops, Belohnung aus Sealed Abyss Artifacts; farmbar (VULKK). Käuflich laut questlog für 285 Kupfer bei den Hexen Areciel, Elowen, Bari und Lyselia; außerdem herstellbar bei Hexen (Blueprint: Faded Abyss Artifact, 1 Abyss Cell + 2 Mercury). Quelle: questlog.gg (Item 75002, Rezept 1000237), egamersworld, esports.gg, VULKK",miss:false,conf:"high",icon:"/assets/_sprites/itemicon_deactived_abyss_artifact.webp"},
  {name:"Gold Bar",cat:"Währung & Progression",detail:"Höchste Wertstufe, nicht direkt ausgebbar. An jeder Bank gegen 500 Silver eintauschbar (und umgekehrt); der Verkauf an normale Händler bringt nur 190 Silver, daher immer zur Bank bringen. Genutzt für Bank-Investitionen (Deposit Box, passives Einkommen) und als schnellste Camp-Funds-Spende. Per Alchemie-Rezept craftbar: Rezept oben im Spire of Insight (Rätsel-Tower südlich von Hernand), hergestellt in einer Witch-Hideout aus Brimstone x3, Mercury x3, Silver Ore x10 (questlog-Rezept 1000157; weitere Rezepte: 1 Golden Apple + 3 Gold Ore bei Hexen, 100 Gold Ore am Schmied). Herstellung/Rezept siehe Crafting- und Hexen-Tab.",loc:"Bank, Schatzkisten, Treasure-(Trader-)Goblins, Welt-Beute, Alchemie (Spire-of-Insight-Rezept). Quelle: PowerPyx, KeenGamer, Game8, thegameswiki",miss:false,conf:"high",icon:"/assets/_sprites/itemicon_prefab_cd_t0000_goldbar_0001.webp"},
  {name:"Hernand Refinement Token",cat:"Währung & Progression",detail:"Refinement-Token, der beim Gear-Upgrade die Crafting-Materialien ersetzt: pro Token steigt ein Ausrüstungsstück eine Stufe ohne Erze, Häute oder Ressourcen. Eingelöst bei Turnali, dem Blacksmith in Hernand City, im Refinement-Menü unter dem Reiter 'Refinement Tokens'. Wirkt laut Item-Text nur bei Ausrüstung, die weniger als fünfmal verfeinert wurde (questlog: 'refined less than five times'); die Guides nennen 'unter Stufe 4', die genaue Grenze ist daher um eine Stufe uneindeutig. Mit Erreichen der Grenze verschwindet die Token-Option. Mehrfach bestätigt (questlog, GamesGG, TheGamer, PC Gamer, Shacknews).",loc:"Belohnung aus Haupt- und Fraktionsquests in Hernand; Einlösung bei Turnali (Hernand City). Quelle: GamesGG, TheGamer, PC Gamer, Shacknews",miss:false,conf:"high",icon:"/assets/_sprites/itemicon_itemupgrade_coin_hernand_00.webp"},
  {name:"Sealed Abyss Artifact",cat:"Währung & Progression",detail:"Verschlossener, polygonaler Würfel an Straßenschreinen/Altären in ganz Pywel. Bleibt im Inventar gesperrt, bis die daran gebundene versteckte Herausforderung abgeschlossen ist (z.B. Gegner mit bestimmter Waffe im Zeitlimit töten). Belohnung danach: ein reguläres Abyss Artifact, ein Faded Abyss Artifact oder ein Abyss Gear. Es gibt 141 davon in der Welt (egamersworld, esports.gg).",loc:"141 feste Fundorte an Straßen-Schreinen/Steinaltären in Pywel. Quelle: egamersworld, esports.gg, GameRant",miss:false,conf:"high",icon:"/assets/_sprites/itemicon_prefab_cd_t0000_abyss_artifact_c_0001.webp"},
  {name:"Silver",cat:"Währung & Progression",detail:"Standard-Handelswährung. Wird für fast alles ausgegeben: Vendoren, Schmiede/Refinement, Rüstung, Camp-Ausbau, Inventarerweiterung und Schließfächer. Umrechnung: 100 Copper = 1 Silver; 500 Silver = 1 Gold Bar an jeder Bank (4 Banken, gemeinsames Konto). Camp-Spende: Seit Patch 2.01.00 (04.09.2026) erhält man für gespendetes Silver die zehnfache Menge Camp Funds (offizielle Notes). Mehrfach bestätigt (Method.gg, PowerPyx, thegameswiki).",loc:"Gegner-Drops, Verkauf von Beute, Quests, Handel. Quelle: Method.gg, PowerPyx, thegameswiki",miss:false,conf:"high",icon:"cd_assets/items/silver.png"},
  {name:"Abyss Gear",cat:"Währung & Progression",detail:"Runen-/Orb-ähnliche Mods, die in Sockel von Waffen/Rüstung gesteckt werden und Statboni oder elementare Effekte (Feuer, Eis, Blitz) gewähren. Die Sockelung erfolgt an einer Witch-Hideout. Erhältlich als Belohnung aus Sealed Abyss Artifacts, aus einzigartigem Welt-Equipment, von Bossen und aus Abyss-Schatzkisten; bei Witches craftbar. Hinweis: Synthese/Cores laufen im eigenen Abyss-Core-Tab, hier nur als Progressions-Belohnungsitem erfasst.",loc:"Sealed-Artifact-Belohnung, Bosse, Abyss-Schatzkisten, Witch-Crafting/Sockelung. Quelle: GameRant, esports.gg, VULKK",miss:false,conf:"medium",icon:"cd_assets/items/abyss-gear.webp"},
  {name:"Delesyia Refinement Token",cat:"Währung & Progression",detail:"Regionale Variante des Refinement-Tokens für das Delesyia-Gebiet. Gleiche Regeln wie Hernand- und Pailune-Token (materialfreies Gear-Upgrade für Ausrüstung, die weniger als fünfmal verfeinert wurde), nur in der zugehörigen Region einlösbar; laut Item-Text beim Schmied Renier. Wird erst im späteren Spielverlauf verfügbar.",loc:"Belohnung aus Haupt-/Fraktionsquests in Delesyia (questlog: u. a. 'Hand over the Delesyian wine', 'Hand over 2 chunks of tender meat'); Einlösung beim Schmied Renier. Quelle: questlog.gg (Item 1003831), TheGamer",miss:false,conf:"high",icon:"/assets/_sprites/itemicon_itemupgrade_coin_delesyia_00.webp"},
  {name:"Demeniss Refinement Token",cat:"Währung & Progression",detail:"Regionaler Refinement-Token, vom Regenten von Demeniss vergeben. Beim Schmied Jofroy eingelöst, deckt er die Materialkosten der Verfeinerung; laut Spieltext nur für Ausrüstung, die weniger als fünfmal verfeinert wurde (Grenze gegenüber der Guide-Angabe „unter Stufe 4“ ingame zu prüfen).",loc:"Belohnung u. a. der Händleraufträge „Kathor's Request“, „Khron's Request“ und „Jofroy's Request“ (Tales of the Demenissian Merchants) sowie der Mission „The Cursed Knight“ (Demeniss Bound). Quelle: questlog.gg (item 1003830)",miss:false,conf:"high",icon:"/assets/_sprites/itemicon_itemupgrade_coin_demeniss_00.webp"},
  {name:"Beighen Refinement Token",cat:"Währung & Progression",detail:"Regionaler Refinement-Token, vom Oberhaupt von Beighen vergeben. Beim Schmied Forgehart eingelöst, deckt er die Materialkosten der Verfeinerung; laut Spieltext nur für Ausrüstung, die weniger als fünfmal verfeinert wurde.",loc:"Belohnung des Händlerauftrags „Richart's Request“ (Tales of the Pailunese Merchants). Quelle: questlog.gg (item 1003833)",miss:false,conf:"high",icon:"/assets/_sprites/itemicon_itemupgrade_coin_beighen_00.webp"},
  {name:"Tommaso Refinement Token",cat:"Währung & Progression",detail:"Regionaler Refinement-Token, vom Bürgermeister von Tommaso vergeben. Beim Schmied Tibo eingelöst, deckt er die Materialkosten der Verfeinerung; laut Spieltext nur für Ausrüstung, die weniger als fünfmal verfeinert wurde.",loc:"Belohnung der Händleraufträge „Tibo's Request“ und „Brookner's Request“ (Tales of the Crimson Desert Merchants). Quelle: questlog.gg (item 1003834)",miss:false,conf:"high",icon:"/assets/_sprites/itemicon_itemupgrade_coin_tashkalp_00.webp"},
  {name:"Varnia Refinement Token",cat:"Währung & Progression",detail:"Regionaler Refinement-Token, vom Bürgermeister von Varnia vergeben. Beim Schmied Samir eingelöst, deckt er die Materialkosten der Verfeinerung; laut Spieltext nur für Ausrüstung, die weniger als fünfmal verfeinert wurde.",loc:"Belohnung der Händleraufträge „Samir's Request“ und „Omar's Request“ (Tales of the Crimson Desert Merchants) sowie der Mission „Pursuit Beyond the Veil“ (Veiled Witch). Quelle: questlog.gg (item 1003851)",miss:false,conf:"high",icon:"/assets/_sprites/itemicon_itemupgrade_coin_varnia_00.webp"},
  {name:"Pailune Refinement Token",cat:"Währung & Progression",detail:"Regionale Variante des Refinement-Tokens für das Pailune-Gebiet. Funktioniert identisch zum Hernand-Token (ersetzt Refinement-Materialien, hebt Gear eine Stufe hoch, bis Stufe 4), kann aber nur bei einem Smithy in der eigenen Region (Pailune) eingelöst werden. Laut Item-Text (questlog 1003832) gilt abweichend von der Guide-Angabe 'bis Stufe 4' die Grenze 'weniger als fünfmal verfeinert'; Herkunft laut questlog u. a. die Missionen 'Hand over the dagger' und 'Hand over 3 short hair hides'; von TheGamer und PC Gamer bestätigt.",loc:"Belohnung aus Haupt-/Fraktionsquests in Pailune; Einlösung bei lokalem Smithy in Pailune. Quelle: TheGamer, PC Gamer",miss:false,conf:"high",icon:"/assets/_sprites/itemicon_itemupgrade_coin_pailune_00.webp"},
  {name:"Bounty Notice",cat:"Schlüssel- & Quest-Item",detail:"Steckbriefe/Kopfgeld-Aushänge, die einzelne Outlaws markieren und Kopfgeld-Nebenquests starten. Bekannte Varianten in Hernand (laut questlog 11): Jeffrey, Simon de Montfort, Alessio, Bianca, Blix, Salvatore, Warren, Ulzok, Haldin, Dante, Billy.",loc:"Von Laternenpfählen in der City of Hernand, am Hernand Farmhouse und in der Muckroot Ranch. Quelle: Game8 / Fextralife",miss:false,conf:"high",icon:"cd_assets/items/bounty-notice.webp"},
  {name:"Church Crypt Key",cat:"Schlüssel- & Quest-Item",detail:"Echtes Quest-/Schlüssel-Item. Wird während der Hauptquest 'Secret at the Church' (Mission 68, Kapitel 5) in Demeniss von der Äbtissin der Kirche von West-Demeniss übergeben und öffnet die Krypta im Hof hinter der Kirche (Abstieg über eine Leiter). In der Krypta führt eine Rätsel-Strongbox (vier Ecken anschlagen, bis alle Symbole leuchten) zum Dagger of Radiance.",loc:"Demeniss, Hauptquest 'Secret at the Church', Kapitel 5. Quelle: crimsondesert.gaming.tools, Game8, Fextralife, VULKK, PowerPyx",miss:true,conf:"high",icon:"/assets/_sprites/itemicon_prefab_cd_t0102_key_0001.webp"},
  {name:"Crane Control Room Key",cat:"Schlüssel- & Quest-Item",detail:"Beschreibung: 'A key that unlocks the crane control room's door. Access is restricted to authorized personnel only.' Erlaubt, den Kran zu bedienen und den Sealed-in-Stone-Questfortschritt im Steinbruch fortzusetzen.",loc:"Während der House-Roberts-Fraktionsquest 'Sealed in Stone' am Karin Quarry. Quelle: Fextralife / Game8",miss:false,conf:"high",icon:"/assets/_sprites/itemicon_prefab_cd_t0102_key_0001.webp"},
  {name:"Engraved Key",cat:"Schlüssel- & Quest-Item",detail:"Beschreibung: 'The wooden key glowed, transforming into an iron key. A mysterious symbol is engraved upon its surface.' Aus dem Shabby Wooden Key hervorgegangener Eisenschlüssel mit eingraviertem Symbol; dient dem Questfortschritt.",loc:"Erhalt durch Abschluss der Quest 'Heart Beyond Borders'. Quelle: Fextralife",miss:false,conf:"high",icon:"/assets/_sprites/itemicon_prefab_cd_t0102_key_0002.webp"},
  {name:"Gold Vein Map",cat:"Schlüssel- & Quest-Item",detail:"Schürf-/Goldader-Karte. Nach dem Verbrauch werden 10 Höhlen mit Golderz-Vorkommen auf der Weltkarte markiert (u.a. Anvil Hill Cave in Demeniss, Desert Lake Gold Mine in Varnia, Guardian's Cave in Delesyia).",loc:"Drop des Bosses Marni's Excavatron im Karin Quarry (questlog-Mission 'Defeat Excavatron') (nördlich von Rocca's Hill, Hernand-Region). Quelle: GameRant / games.gg / Game8 / gaming.tools",miss:false,conf:"high",icon:"/assets/_sprites/itemicon_prefab_cd_t0000_boardpaper_0050.webp"},
  {name:"Hidden Treasure Map Piece 7",cat:"Schlüssel- & Quest-Item",detail:"Teilstück einer versteckten Schatzkarte (Nr. 7) für eine Sammel-/Schatzquest. Eigenständig vom bereits erfassten Notorious Thief's Map Piece. Quelle: Game8 + Fextralife.",loc:"Welt-Sammelobjekt. Quelle: Fextralife.",miss:false,conf:"high",icon:"/assets/_sprites/itemicon_prefab_cd_t0000_boardpaper_0137.webp"},
  {name:"Kuku Iron Pot",cat:"Schlüssel- & Quest-Item",detail:"Ein funktionales Schlüssel-Item und tragbares zwergisches Fertigungsgerät (questlog-Name: 'Kuku Pot', ID 53016; dort als Ausrüstung der Kuku-Bird-Gruppe geführt und zusätzlich über das Rezept 'Kuku Pot' herstellbar; questlog nennt außerdem die Mission 'Talk to the artisan' der Quest 'Invention of the Workshop' als Bezugsquelle). Der Topf nimmt Abyss-Objekte sowie Maschinenteile und Apparaturen auf (230 Plätze, jedoch keine normalen Items wie Nahrung, Waffen, Rüstungen oder Rezepte) und ist der Einstieg in ein tiefes Fertigungssystem für einzigartige Waffen, Rucksäcke, Elementar-Rüstung und Drachenreittier-Komponenten. Weitere Kuku-Items werden bei Grimnir gefertigt, zusätzliche Rezepte schalten sich ab Kapitel 5 (Hexen) und Kapitel 10 (Ironflame-Orcs) frei.",loc:"Erhalten in Kapitel 4 während der Hauptquest \"Mysterious Pot\" in der Kilnden-Werkstatt direkt westlich von Hernand: dort trifft man den Zwerg Grimnir, repariert die Brennöfen und fertigt den ersten Topf; die Bedienung lernt man beim Arbeiter Togrum. Quelle: GameSpot, Fextralife, Sportskeeda, VULKK",miss:false,conf:"high",icon:"cd_assets/items/kuku-iron-pot.webp"},
  {name:"Merchant Delivery Seal",cat:"Schlüssel- & Quest-Item",detail:"Ein offizielles Siegel der Goldleaf Merchant Guild zur Beglaubigung von Handelslieferungen. Es kann nicht verkauft oder weggeworfen werden und dient während der Quest als eines der untersuchten Beweisstücke; sein Auftauchen außerhalb des Guildhouse belastet den Verdächtigen.",loc:"Liegt auf einem runden Tisch in Grimzles Haus im Coalvale Workshop; wird während der Faktionsquest \"Extinguishing the Last Flames\" untersucht. Quelle: Fextralife, crimsondesert.app, thegameswiki",miss:false,conf:"high",icon:"/assets/_sprites/itemicon_prefab_cd_t0000_pendant_0001.webp"},
  {name:"Mysterious Elixir",cat:"Schlüssel- & Quest-Item",detail:"Ein Quest-Lieferobjekt: ein Trank aus unbekannten Zutaten, der nach Ziegenhörnern riecht; die Beschreibung legt nahe, dass die Banditen die gestohlenen Hörner als Zutat verwendeten. Kann nicht konsumiert, verkauft oder weggeworfen werden und dient ausschließlich der Questabgabe.",loc:"Wird während der Quest \"The Man Trapped in the Mire\" aus einer der Kisten neben dem weißen Stein am Banditenlager aufgenommen und anschließend dem erzürnten Rancher als Ausgleich für die gestohlenen Ziegenhörner übergeben. Quelle: Fextralife, PowerPyx, Sportskeeda, GameRant",miss:false,conf:"high",icon:"/assets/_sprites/itemicon_prefab_cd_t0000_potion_0002_r.webp"},
  {name:"Ruby Hilted Golden Dagger",cat:"Schlüssel- & Quest-Item",detail:"Ein goldener Dolch mit rubinbesetztem Griff (questlog-Name: 'Ruby-Set Golden Dagger', ID 1000514), ein Rätsel-Item der Quest 'Traces in the Manor' (Kapitel 3). Zusammen mit dem Sapphire Hilted Golden Dagger bildet er ein Paar: Werden beide Dolche in die zwei Halterungen über dem Kamin im Arbeitszimmer (Study) im Obergeschoss von Glenbright Manor gesteckt, löst dies einen Mechanismus aus, das Bücherregal gleitet beiseite und gibt einen Geheimgang in den Keller frei (mit Cloudcart-Blueprint, Meliaras Elixier-Rezept u.a.).",loc:"Liegt auf einer Wandhalterung im Obergeschoss von Glenbright Manor; Quest 'Traces in the Manor', Kapitel 3. Quelle: GameRant, Game8, VGC",miss:false,conf:"high",icon:"cd_assets/items/ruby-hilted-golden-dagger.webp"},
  {name:"Sapphire Hilted Golden Dagger",cat:"Schlüssel- & Quest-Item",detail:"Ein goldener Dolch mit saphirbesetztem Griff (questlog-Name: 'Sapphire-Set Golden Dagger', ID 1000581), das Gegenstück zum Ruby Hilted Golden Dagger ('Ruby-Set Golden Dagger') in der Quest 'Traces in the Manor' (Kapitel 3). Beide Dolche müssen in die Halterungen über dem Kamin im Arbeitszimmer von Glenbright Manor gesetzt werden, um den geheimen Durchgang hinter dem Bücherregal in den Keller zu öffnen.",loc:"Hinter einem Umgebungsrätsel im Glenbright Manor versteckt: Links neben einer Statue befindet sich ein mit einem Zahnrad verbundener Schrank; man dreht das darin liegende Handrad, bis das Licht des Kronleuchters auf die Statue fällt, woraufhin sich eine Wandnische öffnet und den Dolch freigibt. Quest 'Traces in the Manor', Kapitel 3. Quelle: GameRant, Game8",miss:false,conf:"high",icon:"cd_assets/items/sapphire-hilted-golden-dagger.webp"},
  {name:"Scales of Fairness and Justice",cat:"Schlüssel- & Quest-Item",detail:"Beschreibung: 'An honorable emblem awarded to a knight who fought for fairness and justice.' Wer das Emblem trägt, genießt tiefes Vertrauen der Händler und erhält stets günstige Handelskonditionen.",loc:"Quest-Belohnung (Keepsake). Quelle: Fextralife / gaming.tools / questlog.gg",miss:false,conf:"high",icon:"/assets/_sprites/itemicon_demian_item_scale.webp"},
  {name:"Shabby Wooden Key",cat:"Schlüssel- & Quest-Item",detail:"Beschreibung: 'A gift from a beggar near the Hernand Tavern. Timeworn and dirty, it appears to open nothing.' Wandelt sich später in den Engraved Key. Hinweis: Game8 führt dasselbe Item als 'Old Shabby Key'.",loc:"Vom Bettler nahe der Hernand-Taverne während der 'Mysterious Man'-Quest. Quelle: Fextralife / Game8",miss:false,conf:"high",icon:"/assets/_sprites/itemicon_prefab_cd_t0102_key_0003.webp"},
  {name:"Shai's Pendant",cat:"Schlüssel- & Quest-Item",detail:"Ein leuchtendes Schlüssel-/Story-Item, das eine geheimnisvolle Verbindung zum Abyss besitzt und den Protagonisten mit dem Volk der Shai und den Geheimnissen des Dorfes Pororin verbindet. Es wird von Rulupee zurückgelassen.",loc:"Belohnung der Quest 'Heart Beyond Borders': Man läuft zum Haus westlich des Hernand-Inn, spricht mit Rulupee (Kind mit grüner Kapuze) und fängt deren Katze Jiji auf dem Dach ein. Nach Abschluss verschwindet Rulupee um die Ecke und das Pendant liegt auf dem Boden, wo man es aufsammelt. Quelle: Fextralife, GameSpot, Gamer Guides",miss:false,conf:"high",icon:"/assets/_sprites/itemicon_prefab_cd_t0000_clue_pendant_0001.webp"},
  {name:"St. Halssius Visitor Pass",cat:"Schlüssel- & Quest-Item",detail:"Ein Besuchspass, der während der Quest 'Familiar Curses' Zutritt zu St. Halssius' House of Healing gewährt. Trotz Beschreibung als Pass mit begrenzter Nutzung erlaubt er Kliff tatsächlich beliebigen wiederholten Eintritt: Man legt ihn am Haupttor an der Westseite des Geländes vor, woraufhin die Wachen den Pass prüfen und durchlassen.",loc:"Vom Priester (Alfred) in der Church of Hernand in der Stadt Hernand für 10 Silber erhältlich. Alternativen: eine Halssius-Verkleidung von einem NPC an der Außenmauer (ebenfalls ca. 10 Silber) oder das Hineinschleichen ohne Kauf. Quelle: GameSpot, GameRant, Fextralife",miss:false,conf:"high",icon:"/assets/_sprites/itemicon_prefab_cd_t0000_boardpaper_0035.webp"},
  {name:"Stellen Manor Closet Key",cat:"Schlüssel- & Quest-Item",detail:"Schlüssel, den man aus der Melodie-Strongbox (Tastenreihenfolge 1,3,4,2,1,3,4) im Stellen Manor stiehlt. Öffnet den Kleiderschrank/Wandschrank im Schlafzimmer der oberen Etage; dahinter beginnt der Pfad (Handrad, Buch, Bücherregal hinter dem Widder-Gemälde) zur Folterkammer im Keller, in der das Acria-Schwert liegt.",loc:"Aus der Melodie-Strongbox im Stellen Manor (nordöstlich von Hernand, oberes Stockwerk). Quelle: TheGamer / GameRant / games.gg",miss:false,conf:"high",icon:"/assets/_sprites/itemicon_prefab_cd_t0000_key_0005.webp"},
  {name:"White Crow's Letter",cat:"Schlüssel- & Quest-Item",detail:"Beschreibung: 'A letter from White Crow about Abyss Nexuses.' Quest-Brief des White Crow; kann nicht verkauft werden, dient dem Story-Fortschritt (Abyss-Nexus-Strang).",loc:"Vom White Crow übergeben (nach Einsetzen aller vier Witch's Tokens). Quelle: Game8 / Fextralife",miss:false,conf:"high",icon:"cd_assets/items/white-crow-s-letter.webp"},
  {name:"Witch's Token",cat:"Schlüssel- & Quest-Item",detail:"Quest-Item, das man von jeder der vier regionalen Hexen erhält, nachdem deren Sanctum-Queststrang abgeschlossen und die Hexe erneut besucht wurde. Alle vier in das Loch der Tür eingesetzten Token öffnen das Versteck der sechsten Hexe, des White Crow, in den Wayward Woods.",loc:"Je ein Token von Elowen, Bari, Lyselia und Areciel nach deren Sanctum-Quest. Quelle: VULKK / Game8 / GameRant",miss:false,conf:"high",icon:"cd_assets/items/witch-s-token.webp"},
  {name:"Devil of the Reed Field's Doll",cat:"Schlüssel- & Quest-Item",detail:"Quest-Item (Puppe), das auf einem Altar aufgenommen wird (Missability nicht unabhängig bestätigt).",loc:"Auf einem Altar während der Quest 'The Face Behind the Mask'. Quelle: Game8",miss:false,conf:"medium",icon:"/assets/_sprites/itemicon_reeddevil_doll.webp"},
  {name:"Glenbright Manor Key",cat:"Schlüssel- & Quest-Item",detail:"Eisentür-Schlüssel aus Count Graces Glenbright Manor (questlog: 'A key found in Count Grace's Glenbright Manor. It looks like it unlocks a door leading to one of the manor's restricted, hidden areas.'); Guides führen ihn als 'Grace Manor Iron Door Key' (liegt auf dem Schreibtisch neben dem Diener). Daneben gibt es den 'Glenbright Manor Basement Key' (Guides: 'Grace Manor Basement Key'; in einem Geheimraum hinter einem Gemälde zweier zu Pferd kämpfender Ritter nahe der Treppe; öffnet eine separate verschlossene Tür, nachdem man bereits im Keller ist). Der Keller selbst wird nicht mit diesem Schlüssel betreten, sondern über einen Geheimgang/das Kamin-Dolch-Rätsel erschlossen. Beide Schlüssel stammen aus der Hauptquest 'Traces in the Manor' (Kapitel 3).",loc:"Glenbright/Grace Manor, Hauptquest 'Traces in the Manor', Kapitel 3. Quelle: Game8, The Games Wiki, TheGamer, VGC, Fextralife",miss:true,conf:"medium",icon:"/assets/_sprites/itemicon_prefab_cd_t0102_key_0001.webp"},
  {name:"Grace Manor Basement Key",cat:"Schlüssel- & Quest-Item",detail:"Öffnet eine verschlossene Tür im Keller des Glenbright/Grace Manor (Anwesen von Count Grace). questlog führt das Item als 'Glenbright Manor Basement Key' (ID 802927) und vermerkt: 'Its use is not so clear yet.'",loc:"Im Inneren des Glenbright Manor gefunden (Hauptquest 'Traces in the Manor', Kapitel 3). Quelle: Game8, questlog.gg",miss:false,conf:"medium",icon:"cd_assets/items/grace-manor-basement-key.webp"},
  {name:"Grace Manor Iron Door Key",cat:"Schlüssel- & Quest-Item",detail:"Öffnet die Eisentür im Grace/Glenbright Manor. Identisch mit dem Eintrag 'Glenbright Manor Key' (questlog-Name, ID 802926, DE 'Schlüssel zur eisernen Tür des Glenbright-Anwesens').",loc:"Im Inneren des Glenbright Manor gefunden (Hauptquest 'Traces in the Manor', Kapitel 3). Quelle: Game8, questlog.gg",miss:false,conf:"medium",icon:"cd_assets/items/grace-manor-iron-door-key.webp"},
  {name:"Hidden Treasure Map Piece 8",cat:"Schlüssel- & Quest-Item",detail:"Teilstück einer versteckten Schatzkarte (Nr. 8). Quelle: Fextralife (Key Items).",loc:"Welt-Sammelobjekt. Quelle: Fextralife.",miss:false,conf:"medium",icon:"/assets/_sprites/itemicon_prefab_cd_t0000_boardpaper_0138.webp"},
  {name:"Key to the Spire of the Stars",cat:"Schlüssel- & Quest-Item",detail:"Beschreibung: 'A key given by Grundir. The key is required to enter the Spire of the Stars, which is on the hill behind the Scholastone Institute.' questlog-Name: 'Spire of the Stars Key' (ID 1001197).",loc:"Von Grundir gegeben; laut questlog Belohnung der Missionen 'Observe Octavius's Abyss experiment' und 'Restore the Abyss'. Quelle: questlog.gg, Fextralife",miss:false,conf:"high",icon:"cd_assets/items/key-to-the-spire-of-the-stars.webp"},
  {name:"Memories of Abundance",cat:"Schlüssel- & Quest-Item",detail:"Kristall aus geschichteten Erinnerungen, durchdrungen vom Wissen über verborgene Orte in Hernand; Questfortschritt/Sammelstück.",loc:"Belohnung für das Abschließen der Dragon's-Stone-Chamber-Ruins-Challenge. Quelle: Fextralife / questlog.gg",miss:false,conf:"medium",icon:"/assets/_sprites/itemicon_cd_boss_reward_treasuremap.webp"},
  {name:"Notorious Thief's Map Piece",cat:"Schlüssel- & Quest-Item",detail:"Teilstück einer Schatzkarte des berüchtigten Diebes (questlog führt drei Stücke: 'Notorious Thief's Map Piece 1' bis '3', IDs 803011-803013; Beschreibung: 'A map marking a specific location. The surrounding landmarks should help identify it.'); führt zu einer Schatzbelohnung (u.a. Scorchflame Plate Cloak).",loc:"Im Hernandian-Gebiet / Forest of Wolves gefunden (Piece 1). Quelle: questlog.gg / gaming.tools / Gamer Guides",miss:false,conf:"medium",icon:"cd_assets/items/notorious-thief-s-map-piece.webp"},
  {name:"Ordinary Door Key",cat:"Schlüssel- & Quest-Item",detail:"Ein einfacher, verbrauchbarer Schlüssel, der die meisten gewöhnlichen Türen öffnet und so Zugang zu verschlossenen Räumen und versteckten Bereichen verschafft. Es ist der generische Tür-Schlüssel des Spiels (questlog führt ihn schlicht als 'Key', ID 30041: 'A key. It should open most ordinary doors.'; bei vielen Händlern kaufbar, u. a. Aegrin, Slywek, Sumore, Skeint, Randolph), der beim Durchschreiten einer verschlossenen Tür automatisch aufgebraucht wird. Er ist nicht an eine bestimmte Tür gebunden, funktioniert aber nicht bei eigens benannten Quest-Türen.",loc:"Wird u.a. beim Erkunden von Scorchrock Castle im Süden von Demeniss gefunden; zusätzlich als Beute von Gegnern (geringe Drop-Chance) sowie im Back-Alley-Shop gegen Münzen erhältlich. Quelle: Game8, GAMES.GG, questlog.gg",miss:false,conf:"medium",icon:"cd_assets/items/ordinary-door-key.webp"},
  {name:"Prison Key",cat:"Schlüssel- & Quest-Item",detail:"Beschreibung: 'Standard key used for cells holding criminals.' Öffnet Gefängniszellen.",loc:"In der Welt gefunden. Quelle: Fextralife",miss:false,conf:"medium",icon:"/assets/_sprites/itemicon_prefab_cd_t0102_key_0001.webp"},
  {name:"Seal of Greed - Goldleaf Merchant Guild",cat:"Schlüssel- & Quest-Item",detail:"Quest-Item/Handelsberechtigung der Goldleaf Merchant Guild; dient dem Questfortschritt.",loc:"Von einem Goldleaf-Händler nach Abschluss von Kapitel 2. Quelle: Game8",miss:false,conf:"medium",icon:"/assets/_sprites/itemicon_cd_boss_reward_merchantking.webp"},
  {name:"Spire of Clockwork Key",cat:"Schlüssel- & Quest-Item",detail:"Öffnet das Vordertor der Spire of Clockwork.",loc:"Drop von Lucian Bastier nach Abschluss von Kapitel 8; am Vordertor der Spire verwendet. Quelle: GameRant / Game8",miss:false,conf:"medium",icon:"/assets/_sprites/itemicon_prefab_marni_emp_capsule_0001_parts02.webp"},
  {name:"Sungrove Manor Key",cat:"Schlüssel- & Quest-Item",detail:"Belohnung aus der geheimen Strongbox des Sungrove Manor (Puzzle: einzelne Quadrate drehen, bis das Bild vollständig ist); schaltet weitere Inhalte im Manor frei.",loc:"Strongbox im Sungrove Manor (bei M in Demeniss, oberes Stockwerk am Ende des Korridors). Quelle: questlog.gg / gaming.tools / Gamer Guides / games.gg",miss:false,conf:"medium",icon:"/assets/_sprites/itemicon_prefab_cd_t0000_key_0004.webp"},
  {name:"Thornbriar Dungeon Key",cat:"Schlüssel- & Quest-Item",detail:"Schlüssel zu den Zellen des Thornbriar-Dungeons, von dessen Existenz nur wenige wissen.",loc:"Als Tisch-Item im Iron Mask Prison gefunden. Quelle: questlog.gg / gaming.tools",miss:false,conf:"medium",icon:"/assets/_sprites/itemicon_prefab_cd_t0000_key_0006.webp"},
  {name:"Alden's Poster",cat:"Quest-Dokument & Notiz",detail:"Ein Aushang/Poster von Alden, dessen Aufnahme die Nebenquest \"Alden's Request\" (Hernand Commissions) auslöst. Alden betreibt den Hernand Provisioner's Shop und bittet um Hilfe, mehr Kunden für seinen Laden zu gewinnen. Verfügbar ab Kapitel 3.",loc:"Findet sich am Anschlagbrett (Notice Board) des Goldleaf Guildhouse. Quelle: Fextralife, Game8.",miss:false,conf:"high",icon:"/assets/_sprites/itemicon_prefab_cd_t0000_boardpaper_0184.webp"},
  {name:"Alustin's Letter",cat:"Quest-Dokument & Notiz",detail:"Ein versiegelter Brief von Alustin, der sich für die unhöfliche Art der Zustellung entschuldigt und den Spieler bittet, die dunklen Ausstrahlungen am Scholastone-Institut zu untersuchen. Der Brief muss im Inventar gelesen werden, um den Questfortschritt auszulösen.",loc:"Wird in der Stadt Hernand übergeben: Beim Vorrücken zur orangefarbenen Markierung rempelt ein unbenannter NPC den Spieler an und hinterlässt den Brief; Teil der Hauptquest \"The Words of Alustin\". Erscheint der NPC nicht, hilft Speichern und Neuladen. Quelle: Fextralife, PowerPyx, nerdschalk, Game8",miss:false,conf:"high",icon:"cd_assets/items/alustin-s-letter.webp"},
  {name:"Annabella's Poster",cat:"Quest-Dokument & Notiz",detail:"Ein Aushang von Annabella, dessen Aufnahme die Nebenquest \"Annabella's Request\" auslöst. Annabella betreibt die Hernand Saddlery und bittet darum, einen großschuppigen Fisch (Tench) zu fangen, dessen Schuppen sie für modischere Sättel verwenden will.",loc:"Am Anschlagbrett (Notice Board) auf dem Platz der Stadt Hernand; verfügbar nach Abschluss der Quest \"Where Rumors Gather\". Alternativ kann Annabella direkt an der Hernand Saddlery angesprochen werden. Quelle: Fextralife, Game8.",miss:false,conf:"high",icon:"/assets/_sprites/itemicon_prefab_cd_t0000_boardpaper_0198.webp"},
  {name:"Bounty Notice - Alessio",cat:"Quest-Dokument & Notiz",detail:"Ein Kopfgeldaushang für den Gesetzlosen Alessio, der wegen des Betriebs einer illegalen Organisation und wegen Mordes gesucht wird. Das Item kann nicht verkauft werden und startet das Festsetzen Alessios; bei der Constabulary abgegeben bringt es Silber und Hernand-Beitrags-EXP.",loc:"Wird von einem Laternenpfahl in der Stadt Hernand eingesammelt; Alessio selbst lauert laut Guides südöstlich von Hernand in den Greenfield Highlands nahe dem Ironwood Bandit Camp (MapMaster nennt abweichend: nordöstlich des Sanctum of Penitence; questlog-Missionstext: Mord nahe der Southern Quarry). Quelle: Fextralife, thegameswiki, sportskeeda, crimsondesert.gaming.tools",miss:false,conf:"high",icon:"/assets/_sprites/itemicon_prefab_cd_t0000_boardpaper_0108.webp"},
  {name:"Bounty Notice - Bianca",cat:"Quest-Dokument & Notiz",detail:"Ein Kopfgeldaushang für Bianca, eine Auftragsmörderin, die nahe dem Hillside Manor gesichtet wurde. Das Lesen schaltet die Kopfgeld-Fraktionsquest \"Bounty Notice - Bianca\" (House Celeste) frei; Bianca streift um die Church of Hernand (Suche auf dem Friedhof beginnen), die Belohnung beträgt 5 Silber (bei Tötung die Hälfte) plus 300 Hernand-Contribution.",loc:"Poster erscheint zufällig in der Stadt Hernand (Kapitel 2, Bounty-System aktiv); Bianca selbst bei der Church of Hernand. Quelle: questlog.gg, MapMaster, thegameswiki",miss:false,conf:"medium",icon:"/assets/_sprites/itemicon_prefab_cd_t0000_boardpaper_0081.webp"},
  {name:"Bounty Notice - Blix",cat:"Quest-Dokument & Notiz",detail:"Ein Kopfgeldaushang für den Gesetzlosen Blix (grüner Goblin), der wegen unerlaubten Plünderns von Ruinen gesucht wird. Das Lesen schaltet die Kopfgeld-Fraktionsquest \"Bounty Notice - Blix\" (House Celeste) frei; Blix hält sich nur tagsüber (ca. 6-13 Uhr) in einer kleinen Schlucht am Fuß der Bergwand bei Unicorn Cliff auf. Lebend abgeliefert gibt es die volle Belohnung (15 Silber), bei Tötung die Hälfte.",loc:"Poster erscheint zufällig in der Stadt Hernand (Kapitel 2, Bounty-System aktiv); Blix selbst südöstlich von Hernand bei Unicorn Cliff, westlich des Goldleaf Guildhouse. Quelle: questlog.gg, PowerPyx, GamerGuides, MapMaster",miss:false,conf:"high",icon:"/assets/_sprites/itemicon_prefab_cd_t0000_boardpaper_0107.webp"},
  {name:"Bounty Notice - Jeffrey",cat:"Quest-Dokument & Notiz",detail:"Ein Kopfgeld-Aushang für Jeffrey, der in der Stadt Hernand Geld von Bürgern stiehlt (Taschendiebstahl). Das Lesen bzw. Annehmen schaltet die einführende Kopfgeldquest \"Bounty Notice: Jeffrey\" frei, die zugleich das Bounty-System erklärt und als Belohnung eine Maske gibt.",loc:"Wird zu Beginn von Kapitel 2 von Pedro, dem Hernand-Wachhauptmann, an der Constabulary (Wache) außerhalb der Stadt Hernand erhalten (links vom Plaza-Ausgang). Quelle: Fextralife, Game8.",miss:false,conf:"high",icon:"/assets/_sprites/itemicon_prefab_cd_t0000_boardpaper_0077.webp"},
  {name:"Bounty Notice - Salvatore",cat:"Quest-Dokument & Notiz",detail:"Ein Kopfgeld-Aushang für den gesuchten Gesetzlosen Salvatore. Das Lesen des Dokuments schaltet die Fraktions-/Kopfgeldquest \"Bounty Notice: Salvatore\" frei; Salvatore selbst hält sich im Sunset Valley südlich von Hernand auf und ist eine der neun Gesetzlosen-Bounties der Region.",loc:"Als violettes Poster-Symbol an Anschlagbrettern und Holzpfählen in der Stadt Hernand zu finden. Quelle: Fextralife, Game8, GameRant.",miss:false,conf:"high",icon:"/assets/_sprites/itemicon_prefab_cd_t0000_boardpaper_0082.webp"},
  {name:"Bounty Notice - Simon de Montfort",cat:"Quest-Dokument & Notiz",detail:"Ein Kopfgeld-Aushang für Simon de Montfort, der wegen Honigdiebstahls aus der Pollengarth Apiary gesucht wird. Das Lesen schaltet die Fraktionsquest \"Bounty Notice: Simon de Montfort\" frei; Simon wird zuletzt nahe der Nectarwood Apiary gesehen und soll lebend ausgeliefert werden (bei Tötung nur halbe Belohnung).",loc:"Als violettes Poster-Symbol an Anschlagbrettern und Holzpfählen im Dorf Hernand erhältlich; Simon hält sich im Everfrost Basin südwestlich des Scholastone Institute auf. Quelle: Fextralife, Game8, GameRant, questlog.gg.",miss:false,conf:"high",icon:"/assets/_sprites/itemicon_prefab_cd_t0000_boardpaper_0078.webp"},
  {name:"Bounty Notice - Warren",cat:"Quest-Dokument & Notiz",detail:"Ein Kopfgeld-Aushang für den Gesetzlosen Warren. Das Lesen des Dokuments schaltet die Fraktionsquest \"Bounty Notice: Warren\" frei; Warren hält sich später im Gebiet des Pororin Forest auf.",loc:"Wird an einem Laternenpfahl auf der Muckroot Ranch südöstlich der Stadt Hernand gefunden. Quelle: Fextralife, Game8, questlog.gg.",miss:false,conf:"high",icon:"/assets/_sprites/itemicon_prefab_cd_t0000_boardpaper_0084.webp"},
  {name:"Bran's Poster",cat:"Quest-Dokument & Notiz",detail:"Ein Aushang am Schwarzen Brett, auf dem Bran ein gebrauchtes, gut erhaltenes Spinnrad zum Verkauf anbietet, das er nicht an jeden abgeben will. Das Lesen des Posters schaltet die Fraktionsquest „Bran's Request“ (Hernand Commissions) frei.",loc:"Am Notice Board (Schwarzes Brett) in der Stadt Hernand zu Beginn von Kapitel 3 aufzunehmen; Bran selbst findet man in seinem Laden östlich des Schere-Stein-Papier-Minispiels. Quelle: Game8, Sportskeeda",miss:false,conf:"high",icon:"/assets/_sprites/itemicon_prefab_cd_t0000_boardpaper_0161.webp"},
  {name:"Bruna's Note",cat:"Quest-Dokument & Notiz",detail:"Eine Notiz, die der Spielcharakter Kliff im Verlauf von \"Bruna's Request\" von Bruna überreicht bekommt; sie besagt, dass der belieferte Kunde (Sattler) am Hernand Stable arbeitet, und schickt Kliff dorthin, um Rückmeldung zum neuen Sattelzeug einzuholen.",loc:"Wird während der Quest \"Bruna's Request\" von Bruna in der Equinisher Saddlery überreicht und führt anschließend zum Stable in bzw. nördlich der Stadt Hernand. Quelle: Fextralife, GAMES.GG",miss:false,conf:"high",icon:"/assets/_sprites/itemicon_prefab_cd_t0000_boardpaper_0148.webp"},
  {name:"Bruna's Poster",cat:"Quest-Dokument & Notiz",detail:"Ein nicht verkäuflicher Aushang mit dem Text, dass Bruna, die Sattlerin der Equinisher Saddlery, Hilfe braucht; das Lesen schaltet die Faktionsquest \"Bruna's Request\" frei.",loc:"Wird vom Notice Board (Schwarzes Brett) in der Stadt Hernand abgenommen. Quelle: Fextralife, Game8",miss:false,conf:"high",icon:"/assets/_sprites/itemicon_prefab_cd_t0000_boardpaper_0185.webp"},
  {name:"Empty Ledger",cat:"Quest-Dokument & Notiz",detail:"Ein leeres Kassenbuch, das als Beweisstück in der Goldleaf-Faktionsuntersuchung dient. Es ist eines von drei Beweisstücken, die man am Arbeitsplatz von Grimzle prüft (neben Merchant Delivery Seal und Proof of Stay), um ihn als Verräter zu überführen.",loc:"Liegt auf dem Studiertisch in Grimzles Haus im Coalvale Workshop; untersucht in der Teilquest \"Grimzle, the Ledger Manager\" innerhalb von \"Extinguishing the Last Flames\". Quelle: Fextralife, camzillasmom, GamerGuides",miss:false,conf:"high",icon:"/assets/_sprites/itemicon_prefab_gimmick_item_book_06.webp"},
  {name:"Fee Notice",cat:"Quest-Dokument & Notiz",detail:"Eine Gebührenmitteilung (questlog-Name: 'Tax Notice', ID 1003254: 'A notice listing the taxes Nogle must pay.'), die laut Fextralife dokumentiert, dass Nogle 12 Silber für Gildenbeiträge und Lagernutzungsgebühren zahlte; eines der Beweisstücke, die man bei der Untersuchung von Nogle prüft.",loc:"Im Goldleaf Guildhouse, wo Nogle einen Laden prüft, auf einer Kiste unter dem Weinregal des Ladens; Teil der Teilquest \"Nogle, the Trade Manager\" in \"Extinguishing the Last Flames\". Quelle: Fextralife, camzillasmom",miss:false,conf:"high",icon:"cd_assets/items/fee-notice.webp"},
  {name:"Feed Purchase Receipt",cat:"Quest-Dokument & Notiz",detail:"Eine Futter-Kaufquittung (5 Säcke Heufutter zu je 5 Kupfermünzen, gesamt 25 Kupfer, von Blique, Pferdemanager), die zusammen mit dem Horse Hire Ledger als Beweis in der Untersuchung geprüft wird.",loc:"Auf einer Kiste neben der Eingangstür in Bliques Haus in der Bloomwood Ranch; untersucht in der Teilquest \"Blique, the Horse Manager\" innerhalb von \"Extinguishing the Last Flames\". Quelle: Fextralife, camzillasmom, YouTube-Walkthrough",miss:false,conf:"high",icon:"/assets/_sprites/itemicon_goblin_merchant_warranty.webp"},
  {name:"Guard's Letter",cat:"Quest-Dokument & Notiz",detail:"Ein Lese-Brief voller Sehnsucht nach der Familie; ein Wächter schreibt, dass er seine Angehörigen vermisst. Eines der Beweisstücke, die während der Fraktionsquest \"Extinguishing the Last Flames\" untersucht werden.",loc:"Liegt auf einer Kiste neben dem Vorratssack beim Amboss in Kathans Lager außerhalb des Goldleaf-Gildenhauses. Quelle: Fextralife, Gamer Guides",miss:true,conf:"high",icon:"/assets/_sprites/itemicon_prefab_cd_t0000_boardpaper_0225.webp"},
  {name:"Guard's Report",cat:"Quest-Dokument & Notiz",detail:"Ein Lese-Bericht, der festhält, dass beim Patrouillieren von Grimzles Residenz keine unbefugten Zutritte oder verdächtigen Aktivitäten festgestellt wurden. Wird Shakatu als letztes Beweisstück aus Kathans Aussage übergeben; er schließt daraus, dass nur Nogle und Grimzle die Handelsroute kennen. Teil der Fraktionsquest \"Extinguishing the Last Flames\".",loc:"Liegt auf einer Kiste neben den Fässern in Kathans Lager, wo sich drei Goblins miteinander rangeln, nahe einem weißen Zelt. Quelle: method.gg, camzillasmom",miss:true,conf:"high",icon:"/assets/_sprites/itemicon_goblin_merchant_warranty.webp"},
  {name:"Horn Thief",cat:"Quest-Dokument & Notiz",detail:"Ein Steckbrief bzw. Aushang am Schwarzen Brett, der jemanden sucht, der den Dieb fasst, welcher den Ziegen die Hörner abgeschnitten und gestohlen hat. Das Lesen dieses Posters startet die zur Questreihe \"Hernand in Chaos\" gehörende Hauptquest \"The Man Trapped in the Mire\" und führt in das Lesen von Erinnerungen ein.",loc:"Wird durch das Lesen des Steckbriefs \"Horn Thief\" am Anschlagbrett im frühen Spielverlauf (Kapitel 2, Umfeld Hernand) ausgelöst; vor Ort liest man die Hornlose-Ziege-Erinnerung mittels Laterne und der zuvor erhaltenen Visione. Quelle: Game8, Fextralife, GameRant, crimsondb.gg",miss:false,conf:"high",icon:"/assets/_sprites/itemicon_quest_800180.webp"},
  {name:"Horse Hire Ledger",cat:"Quest-Dokument & Notiz",detail:"Ein Pferdevermietungs-Register (letzter Mieter Zelmigr, 3 Silber Pfand für 3 Brown Herspia Stallion). Es wird Shakatu als Beweis übergeben, weil Blique erkennt, dass der Verräter unter den maskierten Männern ist, die Pferde mieteten.",loc:"Auf dem Tisch am Eingang von Bliques Haus in der Bloomwood Ranch (östlich des Goldleaf Trading Post); untersucht in der Teilquest \"Blique, the Horse Manager\" innerhalb von \"Extinguishing the Last Flames\". Quelle: Fextralife, camzillasmom, crimsondesert.app",miss:false,conf:"high",icon:"/assets/_sprites/itemicon_prefab_gimmick_item_book_06.webp"},
  {name:"Investigative Log: Extinguish the Flames",cat:"Quest-Dokument & Notiz",detail:"Ein Ermittlungsprotokoll (questlog-Name: 'Investigative Log: Extinguishing the Last Flames', ID 1000061), das die Namen der unter Verdacht stehenden Gildenmitglieder (Grimzle, Skrav, Blique, Nogle, Kathan) auflistet; einer davon ist der Verräter in der Goldleaf Merchant Guild (letztlich Grimzle). Das Protokoll dient als Leitfaden für die Befragung von fünf NPCs und das Sammeln der Beweise.",loc:"Wird von Shakatu im Goldleaf Guildhouse übergeben, nachdem das erste Questziel der Faktionsquest \"Extinguishing the Last Flames\" abgeschlossen ist. Quelle: Fextralife, VULKK, GameRant, Game8",miss:false,conf:"high",icon:"cd_assets/items/investigative-log-extinguish-the-flames.webp"},
  {name:"Letter to Younger Sibling",cat:"Quest-Dokument & Notiz",detail:"Ein Lese-Brief eines im Schneesturm gefundenen Soldaten an sein jüngeres Geschwister (questlog-Name: 'Letter to Younger Brother', ID 1001337; Wissenseintrag 'The Soldier Who Never Returned'), erfüllt von brüderlicher Liebe. Reines Story-/Lore-Dokument unter den Schlüssel-Items.",loc:"Auf der Leiche eines im Schneesturm umgekommenen Soldaten. Quelle: Fextralife, Questlog.gg, Gamer Guides",miss:true,conf:"high",icon:"cd_assets/items/letter-to-younger-sibling.webp"},
  {name:"Lost Letter",cat:"Quest-Dokument & Notiz",detail:"Ein Lese-Brief, der von einem mysteriösen Fremden überreicht wird, der danach spurlos verschwindet. Zum Lesen wählt man im Inventar die Dokument-Kategorie (zwischen Postern und Steckbriefen); Kliff übersetzt den unverständlichen Text. Vermittelt Tutorial-/Wissens-Einträge (z. B. Ausdauer oder Geschärfte Sinne).",loc:"Wird von einem verdächtigen Fremden ausgehändigt, der sich danach in Luft auflöst. Quelle: PC Gamer, Fextralife",miss:true,conf:"high",icon:"cd_assets/items/lost-letter.webp"},
  {name:"Missing Wooly",cat:"Quest-Dokument & Notiz",detail:"Ein Aushang über ein verschwundenes Schaf namens Wooly. Nach dem Lesen wird daraus die Mission 'Missing Companion' auf der Karte freigeschaltet. Einer der vier Springtide-Mill-Aushänge (neben Stolen/Missing Cows, Horn Thief, Strange Noises from the Cave), deren Abschluss die Hauptquest 'The Dark Veil' freischaltet.",loc:"An der Anschlagtafel bei der Springtide Mill im Hernand-Gebiet, nachdem die Mühle befreit wurde, während der Quest 'Where Misery Gathers' (Kapitel 2: Golden Greed). Quelle: Fextralife, Questlog.gg, PowerPyx",miss:false,conf:"high",icon:"/assets/_sprites/itemicon_quest_800181.webp"},
  {name:"Note with a Suspicious Symbol",cat:"Quest-Dokument & Notiz",detail:"Eine Notiz mit einem verdächtigen Symbol (Outlaw-Token), die jeder Gesetzlose in Pywel beim Fangen oder Töten fallen lässt. Sie kann an Milizionäre in Pywel verschenkt werden und gewährt pro Notiz über 30 Vertrauen; drei Notizen plus ein weiteres Item ergeben volles Vertrauen, woraufhin die Milizionäre Geschenke wie Munition geben.",loc:"Drop von Outlaws in Pywel (eine Notiz pro festgenommenem oder getötetem Gesetzlosen). Quelle: Fextralife, Game8, thegameswiki, gamerblurb",miss:false,conf:"high",icon:"/assets/_sprites/itemicon_prefab_cd_t0000_foldednote_0001.webp"},
  {name:"Proof of Stay",cat:"Quest-Dokument & Notiz",detail:"Ein Lese-Dokument, das als Beweisstück in der Fraktionsquest \"Extinguishing the Last Flames\" dient. Der Text belegt, dass Skrav für 6 Silbermünzen das vierte Zimmer im zweiten Stock des Demeniss-Gasthauses (ausgestellt von Linda) bewohnt hat, und wird Shakatu vorgelegt, um ihn an das gestohlene Hauptbuch in Grimzles Obhut zu erinnern.",loc:"Liegt auf einem Tisch in der Holzfäller-Werkstatt (Scheune) nahe Grimzles Haus im Coalvale-Workshop; die Tür ist verschlossen und der Questmarker führt hin. Teil der Quest \"Grimzle, the Ledger Manager\" innerhalb von \"Extinguishing the Last Flames\". Quelle: Fextralife, camzillasmom",miss:true,conf:"high",icon:"/assets/_sprites/itemicon_goblin_merchant_warranty.webp"},
  {name:"Renee's Poster",cat:"Quest-Dokument & Notiz",detail:"Ein Aushang der Metzgerin Renee; das Lesen schaltet die Fraktionsquest „Renee's Request“ (Hernand Commissions) frei. Renee bittet darin um Hilfe, für einen langjährigen Kunden Fish Porridge zuzubereiten.",loc:"Am Notice Board in der Stadt Hernand zu finden; danach spricht man Renee in der Stadt persönlich an. Quelle: Game8, The Games Wiki",miss:false,conf:"high",icon:"/assets/_sprites/itemicon_prefab_cd_t0000_boardpaper_0199.webp"},
  {name:"Rhett's Poster",cat:"Quest-Dokument & Notiz",detail:"Ein Aushang vom Schwarzen Brett, der die Faktions-/Nebenquest \"Rhett's Request\" freischaltet, sobald man ihn liest und lernt. Die eigentliche Quest startet erst, wenn man danach den Schmied Rhett anspricht.",loc:"Wird vom Notice Board (Schwarzes Brett) am Plaza in der Stadt Hernand gelesen; alternativ wird die Quest nach Abschluss anderer Hernand-Commissions wie Renee's oder Turnali's Request verfügbar. Quelle: Game8, GameRant",miss:false,conf:"high",icon:"/assets/_sprites/itemicon_prefab_cd_t0000_boardpaper_0044.webp"},
  {name:"Royal Delivery Note",cat:"Quest-Dokument & Notiz",detail:"Eine vom königlichen Lieferposten stammende Notiz (questlog-Name: 'Royal Trading Post Note', ID 1002475, DE 'Königliche Liefernotiz'), die das Ziel einer königlichen Lieferung beschreibt; sie verrät, dass der gesuchte Kunde zum Lioncrest Manor gereist ist, und treibt \"Bruna's Request\" voran. Kann nicht verkauft oder weggeworfen werden.",loc:"Wird am Royal Trading Post in der Stadt Hernand erlangt, indem man den Adligen (Noble) mit rotem Hut wiederholt anspricht, bis man die Notiz erhält. Quelle: Game8, Fextralife",miss:false,conf:"high",icon:"cd_assets/items/royal-delivery-note.webp"},
  {name:"Sealed Letter",cat:"Quest-Dokument & Notiz",detail:"Ein Brief von einer geheimnisvollen Frau, der durch mystische Kraft versiegelt ist, sodass sein Inhalt zunächst nicht gelesen werden kann. Als Schlüssel-Item kann er nicht verkauft werden. Im weiteren Hauptquestverlauf wird er entsiegelt (Unsealed Letter) und enthüllt, dass die Hexen ein besonderes Item gegen den Zerfall des Abyss fertigen können.",loc:"Wird erbeutet, indem man den gefesselten Adligen in den Kanälen (Sewers) während der Quest \"True Wisdom in Kindness\" befreit; einsehbar bei den lila Schlüssel-Items oben im Inventar. Später gibt Damiane in der Hauptquest \"The Missing Seal\" die entsiegelte Fassung. Quelle: Fextralife, PC Gamer, Gamer Guides",miss:false,conf:"high",icon:"/assets/_sprites/itemicon_cd_seal_epistle.webp"},
  {name:"Shakatu's Letter",cat:"Quest-Dokument & Notiz",detail:"Ein Brief von Shakatu, der gehört hat, dass man sich auf Howling Hill niedergelassen hat, und sich für die geleistete Hilfe bedankt, indem er ein bescheidenes Geschenk für das neue Heim ankündigt. Reines Lese-Dokument ohne funktionalen Nutzen.",loc:"Wird durch Interaktion mit der Drachenkopf-Statue (Drachen-Totem) im Schrein-Bereich des Lagers auf Howling Hill erhalten. Man muss um die Rückseite des Totems herumgehen, bis die Interaktion erscheint, da der Brief dort und nicht an der dekorativen Vorderseite versteckt ist. Teil der Hauptquest 'A Gentle Touch' aus der Pioneering-Questreihe (Kapitel 3: Howling Hill). Quelle: Fextralife, Nerdschalk, Camzillasmom, PowerPyx",miss:false,conf:"high",icon:"/assets/_sprites/itemicon_prefab_cd_t0000_boardpaper_0034.webp"},
  {name:"Stolen Cows",cat:"Quest-Dokument & Notiz",detail:"Ein Aushang über gestohlene Kühe (von Bremer aus dem Hernand-Bauernhof; questlog-Name des Posters: 'Missing Cows', ID 1002141, DE 'Verschwundene Kühe'), der von der Anschlagtafel genommen und gelesen werden kann. Das Lesen schaltet die Quest 'Trial After Trial' frei; einer der vier Aushänge, deren Abschluss zu 'The Dark Veil' führt.",loc:"An der Anschlagtafel bei der Springtide Mill im Hernand-Gebiet (nach Befreiung der Mühle) während der Quest 'Where Misery Gathers' (Kapitel 2: Golden Greed). Quelle: Fextralife, PowerPyx",miss:false,conf:"high",icon:"cd_assets/items/stolen-cows.webp"},
  {name:"Strange Noises from the Cave",cat:"Quest-Dokument & Notiz",detail:"Ein Aushang, der von seltsamen Geräuschen aus einer Höhle südlich von Hernand berichtet. Das Lesen schaltet die Quest 'Secrets Hidden in the Dark' frei; einer der vier Aushänge, deren Abschluss die Hauptquest 'The Dark Veil' freischaltet.",loc:"An der Anschlagtafel bei der Springtide Mill, südlich der Stadt Hernand (nach Befreiung der Mühle), während der Quest 'Where Misery Gathers' (Kapitel 2: Golden Greed). Quelle: Fextralife, Questlog.gg, GamerGuides, PowerPyx",miss:false,conf:"high",icon:"/assets/_sprites/itemicon_quest_800192.webp"},
  {name:"Tack Keeper's Note",cat:"Quest-Dokument & Notiz",detail:"Eine vom Sattelwart (Tack Keeper) hinterlassene Notiz (questlog-Name: 'Saddler's Note', ID 1002415, DE 'Notiz der Sattlerin': 'A note found at the stable in Hernand.') im Rahmen von \"Bruna's Request\"; sie erklärt, dass der gesuchte Sattler vorübergehend abwesend ist und zum Royal Trading Post weitergezogen ist.",loc:"Liegt auf einem Fass hinter dem Gebäude am Stable (Stall) nördlich der Stadt Hernand und ist als violettes Dokument-Symbol auf der Minimap markiert; gehört zur Quest \"Bruna's Request\". Quelle: Game8, The Games Wiki",miss:false,conf:"high",icon:"cd_assets/items/tack-keeper-s-note.webp"},
  {name:"Tales of Sunset Valley",cat:"Quest-Dokument & Notiz",detail:"Eine Sammlung der düsteren Geschichten von Sunset Valley, darunter bizarre Erzählungen über böse Geister, die im Schilf flüstern, und eine Vogelscheuche, die in den Wahnsinn führt. Lesbares Buch-Dokument.",loc:"Auffindbar im Gebiet Sunset Valley/Hernand; in den Datenbanken als Buch geführt (interne ID book_hernand_story). Fextralife kategorisiert es als Key Item, inhaltlich ist es ein Lesebuch. Quelle: Fextralife, Questlog.gg, crimsondesert.gaming.tools",miss:false,conf:"high",icon:"/assets/_sprites/itemicon_prefab_gimmick_item_book_07.webp"},
  {name:"Tavern Ledger",cat:"Quest-Dokument & Notiz",detail:"Ein Schankbuch der Hernand-Schenke (Namen Nogle und Grimzle, 50 Kupfermünzen, 10 Flaschen Wein am hintersten Tisch). Es wird Shakatu als Beweis vorgelegt, dass Nogle die Handelsroute preisgab, als er mit Grimzle in der Taverne trank.",loc:"Im Goldleaf Guildhouse, wo Nogle einen Laden prüft; auf einer Kiste unter der Fleischware des Ladens, neben gestapelten Fässern. Teil der Teilquest \"Nogle, the Trade Manager\" in \"Extinguishing the Last Flames\". Quelle: Fextralife, camzillasmom",miss:false,conf:"high",icon:"/assets/_sprites/itemicon_goblin_merchant_warranty.webp"},
  {name:"Tina's Poster",cat:"Quest-Dokument & Notiz",detail:"Ein Aushang der Schneiderin Tina; nach dem Aufnehmen wird ab Kapitel 3 die Fraktionsquest „Tina's Request“ (Hernand Commissions) verfügbar. Tina hat einen Hut fertig, kann ihren Laden aber nicht verlassen und bittet um die Auslieferung.",loc:"Am Notice Board in der Stadt Hernand zu finden; Tinas Laden liegt direkt neben dem Ausrüstungsladen (Rhett's Shop). Quelle: Game8, Fextralife",miss:false,conf:"high",icon:"/assets/_sprites/itemicon_prefab_cd_t0000_boardpaper_0160.webp"},
  {name:"Trade Schedule Log",cat:"Quest-Dokument & Notiz",detail:"Ein Handelsplan-Logbuch (12 Ballen Seide, 5 Silbermünzen, Transaktionsmanager Nogle; Notiz: die Seide wird von der Goldleaf-Gilde zum Hafen transportiert). Es wird als Beweis vorgelegt; Shakatu hält Skrav daraufhin für verdächtig, was aber noch nicht reicht, um den wahren Verräter zu fassen.",loc:"Hinten im Stoffladen am Goldleaf Trading Post, auf einer Kiste, dort wo man mit Skrav gesprochen hat; Teil der Teilquest \"Skrav, the Trade Manager\" in \"Extinguishing the Last Flames\". Quelle: Fextralife, camzillasmom, GAMERPILLAR",miss:false,conf:"high",icon:"/assets/_sprites/itemicon_prefab_cd_t0000_boardpaper_0223.webp"},
  {name:"Turnali's Poster",cat:"Quest-Dokument & Notiz",detail:"Ein Aushang, der die Faktionsquest \"Turnali's Request\" freischaltet, wenn man ihn liest und lernt. Im Text bittet der Schmied Turnali um Hilfe; die Quest führt in die Spielsysteme Holzfällen (Logging) und Ausrüstungs-Refinement ein.",loc:"Wird vom Notice Board (Schwarzes Brett) am Plaza in der Stadt Hernand abgenommen; alternativ kann man direkt zu Turnalis Schmiede nordöstlich des Bretts gehen. Quelle: Fextralife, Game8",miss:false,conf:"high",icon:"/assets/_sprites/itemicon_prefab_cd_t0000_boardpaper_0201.webp"},
  {name:"Turnali's Smithy Flyer",cat:"Quest-Dokument & Notiz",detail:"Ein Werbeflyer für die Schmiede, scheinbar von Turnali selbst verfasst. Das Lesen erklärt die Ausrüstungs-Veredelung (Refinement): An der Schmiede lässt sich Ausrüstung mit genügend Materialien aufwerten.",loc:"In der Stadt Hernand während der Fraktionsquest „Turnali's Request“; Turnali übergibt ihn zusammen mit einem Bekker Shield und 10x Timber als Belohnung für das Aushändigen des Fine Timber. Quelle: Fextralife, Sportskeeda",miss:false,conf:"high",icon:"/assets/_sprites/itemicon_prefab_cd_t0000_boardpaper_0245.webp"},
  {name:"Ugmon's Poster",cat:"Quest-Dokument & Notiz",detail:"Ein Aushang von Ugmon, der jemanden mit ausgeprägtem Geschmacks- und Geruchssinn sucht. Das Lesen schaltet die Fraktionsquest „Ugmon's Request“ (Hernand Commissions) frei.",loc:"Am Notice Board in der Stadt Hernand (ab Kapitel 3); Ugmon selbst sitzt im Goldleaf Guildhouse nahe Unicorn Cliff. Quelle: Camzillasmom, Nerdschalk",miss:false,conf:"high",icon:"/assets/_sprites/itemicon_prefab_cd_t0000_boardpaper_0190.webp"},
  {name:"Unsealed Letter",cat:"Quest-Dokument & Notiz",detail:"Beschrieben als \"ein Brief, entsiegelt, da die mystische Kraft verblasst ist\". Es ist der Brief der White Crow, dessen Siegel sich löst; er warnt vor der bröckelnden Grenze zwischen Abyss und Wirklichkeit. Beim Lesen erfährt man, dass Hexen ein besonderes Mittel gegen den Abyss-Zerfall herstellen können, was die Fraktionsquest \"The Witch of Wisdom\" auslöst.",loc:"Wird von Damiane in der Stadt Hernand im Verlauf der Hauptquest \"The Missing Seal\" ausgehändigt und sofort im Inventar (lila Schlüssel-Item) gelesen. Quelle: Fextralife, PowerPyx",miss:false,conf:"high",icon:"/assets/_sprites/itemicon_prefab_cd_t0000_boardpaper_0241.webp"},
  {name:"Wisdom between Donation and Fruition",cat:"Quest-Dokument & Notiz",detail:"Eine Notiz mit Details zu Bekehrungs- bzw. Missionierungsaktivitäten (conversion activities). Reines Lese-Dokument, das nach der Übergabe gelesen werden soll.",loc:"Wird in der Church of Hernand (Solumen-Orden, Stadt Hernand) erhalten; ein Priester auf der rechten Seite der Kirche begrüßt den Spieler und überreicht die Notiz. Quelle: Fextralife, crimsondesert.gaming.tools, Questlog.gg, GamerGuides",miss:false,conf:"high",icon:"/assets/_sprites/itemicon_prefab_cd_t0000_boardpaper_0239.webp"},
  {name:"Ugmon's Note",cat:"Quest-Dokument & Notiz",detail:"Eine als Key Item geführte Notiz von Ugmon vom Handelszentrum Goldleaf Guildhouse. Reines Lese-/Questdokument im Rahmen von „Ugmon's Request“; kann nicht verkauft werden.",loc:"Im Verlauf von „Ugmon's Request“ rund um Ugmon am Goldleaf Guildhouse erhältlich; die genaue Aufnahme ist in den Quellen nicht näher spezifiziert. Quelle: Fextralife",miss:false,conf:"medium",icon:"/assets/_sprites/itemicon_prefab_cd_t0000_boardpaper_0148.webp"},
];
